	GO
	CREATE INDEX IxGiaTraCuu ON dbo.GiaNguyenLieu(MaNguyenLieu,KhuVuc,NgayApDung DESC) INCLUDE(MaDonVi,GiaThamKhao);
	CREATE INDEX IxThucDonNguoiNgay ON dbo.ThucDon(MaNguoiDung,NgayBatDau,NgayKetThuc);
	CREATE INDEX IxChiTietMon ON dbo.ChiTietThucDon(MaMonAn,NgayDung) INCLUDE(MaThucDon,SoKhauPhan);
	CREATE INDEX IxThanhPhanNguyenLieu ON dbo.ThanhPhanCongThuc(MaNguyenLieu,MaCongThuc);
	CREATE INDEX IxMonDanhMuc ON dbo.MonAn(MaDanhMuc);
	CREATE INDEX IxDanhGiaMon ON dbo.DanhGiaMonAn(MaMonAn) INCLUDE(SoSao);
	CREATE INDEX IxSnapshotThucDon ON dbo.DanhGiaDinhDuongThucDon(MaThucDon,ThoiDiemDanhGia DESC);
