	 EXEC dbo.SpKiemTraQuanTri @MaQuanTri;
	 IF EXISTS(SELECT 1 FROM dbo.NguyenLieu WITH(UPDLOCK,HOLDLOCK) WHERE MaNguyenLieu=@Ma)
	 UPDATE dbo.NguyenLieu SET TenNguyenLieu=@Ten,MoTa=@MoTa WHERE MaNguyenLieu=@Ma;
	 ELSE INSERT dbo.NguyenLieu(MaNguyenLieu,TenNguyenLieu,MoTa) VALUES(@Ma,@Ten,@MoTa);
			IF @TranBanDau=0 COMMIT TRANSACTION;
		END TRY
		BEGIN CATCH
			IF @TranBanDau=0 AND XACT_STATE()<>0 ROLLBACK TRANSACTION;
			ELSE IF @TranBanDau>0 AND XACT_STATE()=1 ROLLBACK TRANSACTION ProcSave;
			-- Nếu giao dịch của caller đã doomed (XACT_STATE=-1), caller phải rollback toàn bộ.
			THROW;
		END CATCH;
	END;
	GO
