			-- Nếu giao dịch của caller đã doomed (XACT_STATE=-1), caller phải rollback toàn bộ.
			THROW;
		END CATCH;
	END;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpLuuCheDoAn
	 @MaQuanTri NVARCHAR(20),@Ma NVARCHAR(20),@Ten NVARCHAR(100),@MoTa NVARCHAR(500)=NULL
	AS
	BEGIN
		SET NOCOUNT ON;
		SET XACT_ABORT ON;
		DECLARE @TranBanDau INT=@@TRANCOUNT;
		BEGIN TRY
			IF @TranBanDau=0 BEGIN TRANSACTION;
			ELSE SAVE TRANSACTION ProcSave;
		IF @MaQuanTri IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@MaQuanTri,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@MaQuanTri không được để trống.',1;
		IF @Ma IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@Ma,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@Ma không được để trống.',1;
		IF @Ten IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@Ten,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@Ten không được để trống.',1;
	 EXEC dbo.SpKiemTraQuanTri @MaQuanTri;
	 IF EXISTS(SELECT 1 FROM dbo.CheDoAn WITH(UPDLOCK,HOLDLOCK) WHERE MaCheDoAn=@Ma)
	 UPDATE dbo.CheDoAn SET TenCheDoAn=@Ten,MoTa=@MoTa WHERE MaCheDoAn=@Ma;
	 ELSE INSERT dbo.CheDoAn(MaCheDoAn,TenCheDoAn,MoTa) VALUES(@Ma,@Ten,@MoTa);
			IF @TranBanDau=0 COMMIT TRANSACTION;
		END TRY
		BEGIN CATCH
			IF @TranBanDau=0 AND XACT_STATE()<>0 ROLLBACK TRANSACTION;
			ELSE IF @TranBanDau>0 AND XACT_STATE()=1 ROLLBACK TRANSACTION ProcSave;
			-- Nếu giao dịch của caller đã doomed (XACT_STATE=-1), caller phải rollback toàn bộ.
			THROW;
		END CATCH;
	END;
	GO
