		IF @KyHieu IS NULL OR LEN(LTRIM(RTRIM(REPLACE(REPLACE(REPLACE(@KyHieu,NCHAR(9),N' '),NCHAR(10),N' '),NCHAR(13),N' '))))=0 THROW 51031,N'@KyHieu không được để trống.',1;
