		(
			user_id NVARCHAR(20) NOT NULL,
			answers NVARCHAR(MAX) NOT NULL,
			completed INT NOT NULL
				CONSTRAINT DF_UserPreferences_Completed DEFAULT (0),
			survey_shown INT NOT NULL
				CONSTRAINT DF_UserPreferences_SurveyShown DEFAULT (0),

			CONSTRAINT PK_UserPreferences
				PRIMARY KEY (user_id),

			CONSTRAINT FK_UserPreferences_NguoiDung
				FOREIGN KEY (user_id)
				REFERENCES dbo.NguoiDung(MaNguoiDung),

			CONSTRAINT CK_UserPreferences_Completed
				CHECK (completed IN (0, 1)),

			CONSTRAINT CK_UserPreferences_SurveyShown
				CHECK (survey_shown IN (0, 1))
		);
	END;
