	DECLARE @DanhSach TABLE
	(
		TenProcedure SYSNAME PRIMARY KEY
	);

	INSERT INTO @DanhSach(TenProcedure)
	VALUES
	(N'SpLuuMonAn'),
	(N'SpXoaMonAn'),

	(N'SpLuuCongThuc'),
	(N'SpDatTrangThaiCongThuc'),
	(N'SpXoaCongThuc'),

	(N'SpLuuThanhPhanCongThuc'),
	(N'SpXoaThanhPhanCongThuc'),

	(N'SpLuuBuocCheBien'),
	(N'SpXoaBuocCheBien'),

	(N'SpLuuVideoHuongDan'),

	(N'SpLuuGiaNguyenLieu'),
	(N'SpLuuQuyDoiDonVi'),
	(N'SpLuuThongTinDinhDuong'),

	(N'SpLuuDanhMucMonAn'),
	(N'SpLuuNguyenLieu'),
	(N'SpLuuKhauVi'),
	(N'SpLuuCheDoAn'),
	(N'SpLuuDonViTinh'),
	(N'SpXoaDanhMuc'),

	(N'SpDatKhauViMonAn'),
	(N'SpDatCheDoAnMonAn');


	DECLARE
		@Ten SYSNAME,
		@Definition NVARCHAR(MAX);


	DECLARE CurNoiDung CURSOR LOCAL FAST_FORWARD
	FOR
	SELECT TenProcedure
	FROM @DanhSach;


	OPEN CurNoiDung;

	FETCH NEXT FROM CurNoiDung INTO @Ten;

	WHILE @@FETCH_STATUS = 0
	BEGIN

		SET @Definition = OBJECT_DEFINITION
		(
			OBJECT_ID(N'dbo.' + @Ten)
		);

		IF @Definition IS NULL
		BEGIN
			PRINT N'BỎ QUA - Không tồn tại: ' + @Ten;
		END
		ELSE IF @Definition LIKE N'%SpKiemTraQuanTriNoiDung%'
		BEGIN
			PRINT N'ĐÃ ĐÚNG QUYỀN: ' + @Ten;
		END
		ELSE IF @Definition LIKE N'%SpKiemTraQuanTri%'
		BEGIN

			/* Đổi CREATE PROCEDURE thành ALTER PROCEDURE */
			SET @Definition =
				REPLACE
				(
					@Definition,
					N'CREATE PROCEDURE',
					N'ALTER PROCEDURE'
				);

			SET @Definition =
				REPLACE
				(
					@Definition,
					N'CREATE PROC',
					N'ALTER PROC'
				);

			/* Đổi procedure kiểm tra quyền */
			SET @Definition =
				REPLACE
				(
					@Definition,
					N'SpKiemTraQuanTri',
					N'SpKiemTraQuanTriNoiDung'
				);

			BEGIN TRY

				EXEC sys.sp_executesql @Definition;

				PRINT N'ĐÃ CHUYỂN -> QUẢN TRỊ NỘI DUNG: ' + @Ten;

			END TRY
			BEGIN CATCH

				PRINT N'LỖI tại ' + @Ten
					  + N': '
					  + ERROR_MESSAGE();

			END CATCH;

		END
		ELSE
		BEGIN
			PRINT N'CẦN KIỂM TRA THỦ CÔNG - Không thấy SpKiemTraQuanTri: '
				  + @Ten;
		END;


		FETCH NEXT FROM CurNoiDung INTO @Ten;
	END;


	CLOSE CurNoiDung;
	DEALLOCATE CurNoiDung;
	GO
	USE QuanLyThucDon;
	GO
	DECLARE @DanhSach TABLE
	(
		TenProcedure SYSNAME PRIMARY KEY
	);

	INSERT INTO @DanhSach(TenProcedure)
	VALUES
	(N'SpLayNguoiDung'),
	(N'SpDatTrangThaiNguoiDung'),
	(N'SpThongKeSuDung');


	DECLARE
		@Ten SYSNAME,
		@Definition NVARCHAR(MAX);


	DECLARE CurHeThong CURSOR LOCAL FAST_FORWARD
	FOR
	SELECT TenProcedure
	FROM @DanhSach;


	OPEN CurHeThong;

	FETCH NEXT FROM CurHeThong INTO @Ten;

	WHILE @@FETCH_STATUS = 0
	BEGIN

		SET @Definition = OBJECT_DEFINITION
		(
			OBJECT_ID(N'dbo.' + @Ten)
		);

		IF @Definition IS NULL
		BEGIN
			PRINT N'BỎ QUA - Không tồn tại: ' + @Ten;
		END
		ELSE IF @Definition LIKE N'%SpKiemTraQuanTriHeThong%'
		BEGIN
			PRINT N'ĐÃ ĐÚNG QUYỀN: ' + @Ten;
		END
		ELSE IF @Definition LIKE N'%SpKiemTraQuanTri%'
		BEGIN

			SET @Definition =
				REPLACE
				(
					@Definition,
					N'CREATE PROCEDURE',
					N'ALTER PROCEDURE'
				);

			SET @Definition =
				REPLACE
				(
					@Definition,
					N'CREATE PROC',
					N'ALTER PROC'
				);

			SET @Definition =
				REPLACE
				(
					@Definition,
					N'SpKiemTraQuanTri',
					N'SpKiemTraQuanTriHeThong'
				);

			BEGIN TRY

				EXEC sys.sp_executesql @Definition;

				PRINT N'ĐÃ CHUYỂN -> QUẢN TRỊ HỆ THỐNG: ' + @Ten;

			END TRY
			BEGIN CATCH

				PRINT N'LỖI tại ' + @Ten
					  + N': '
					  + ERROR_MESSAGE();

			END CATCH;

		END
		ELSE
		BEGIN
			PRINT N'CẦN KIỂM TRA THỦ CÔNG - Không thấy SpKiemTraQuanTri: '
				  + @Ten;
		END;


		FETCH NEXT FROM CurHeThong INTO @Ten;
	END;


	CLOSE CurHeThong;
	DEALLOCATE CurHeThong;
	GO
