	USE QuanLyThucDon;
	GO
	IF NOT EXISTS
	(
		SELECT 1
		FROM dbo.NguoiDung
		WHERE MaNguoiDung = N'ND005'
	)
	AND NOT EXISTS
	(
		SELECT 1
		FROM dbo.NguoiDung
		WHERE ThuDienTu = N'hethong@thucdon.vn'
	)
	BEGIN

		INSERT INTO dbo.NguoiDung
		(
			MaNguoiDung,
			HoTen,
			ThuDienTu,
			MatKhauBam,
			VaiTro,
			TrangThai
		)
		SELECT
			N'ND005',
			N'Quản trị hệ thống',
			N'hethong@thucdon.vn',
			ND.MatKhauBam,
			N'Quản trị hệ thống',
			N'Đang hoạt động'
		FROM dbo.NguoiDung ND
		WHERE ND.MaNguoiDung = N'ND001';

	END;
