	INSERT INTO @PhanQuyen
	VALUES
	/* QUẢN TRỊ HỆ THỐNG */
	(N'SpLayNguoiDung',               N'SpKiemTraQuanTriHeThong'),
	(N'SpDatTrangThaiNguoiDung',      N'SpKiemTraQuanTriHeThong'),
	(N'SpThongKeSuDung',              N'SpKiemTraQuanTriHeThong'),

	/* QUẢN TRỊ NỘI DUNG */
	(N'SpDatCheDoAnMonAn',            N'SpKiemTraQuanTriNoiDung'),
	(N'SpDatKhauViMonAn',             N'SpKiemTraQuanTriNoiDung'),
	(N'SpDatTrangThaiCongThuc',       N'SpKiemTraQuanTriNoiDung'),
	(N'SpLuuBuocCheBien',             N'SpKiemTraQuanTriNoiDung'),
	(N'SpLuuCheDoAn',                 N'SpKiemTraQuanTriNoiDung'),
	(N'SpLuuCongThuc',                N'SpKiemTraQuanTriNoiDung'),
	(N'SpLuuDanhMucMonAn',            N'SpKiemTraQuanTriNoiDung'),
	(N'SpLuuDonViTinh',               N'SpKiemTraQuanTriNoiDung'),
	(N'SpLuuGiaNguyenLieu',           N'SpKiemTraQuanTriNoiDung'),
	(N'SpLuuKhauVi',                  N'SpKiemTraQuanTriNoiDung'),
	(N'SpLuuMonAn',                   N'SpKiemTraQuanTriNoiDung'),
	(N'SpLuuNguyenLieu',              N'SpKiemTraQuanTriNoiDung'),
	(N'SpLuuNguyenLieuThayThe',       N'SpKiemTraQuanTriNoiDung'),
	(N'SpLuuQuyDoiDonVi',             N'SpKiemTraQuanTriNoiDung'),
	(N'SpLuuThanhPhanCongThuc',       N'SpKiemTraQuanTriNoiDung'),
	(N'SpLuuThongTinDinhDuong',       N'SpKiemTraQuanTriNoiDung'),
	(N'SpLuuVideoHuongDan',           N'SpKiemTraQuanTriNoiDung'),
	(N'SpXoaBuocCheBien',             N'SpKiemTraQuanTriNoiDung'),
	(N'SpXoaCongThuc',                N'SpKiemTraQuanTriNoiDung'),
	(N'SpXoaDanhMuc',                 N'SpKiemTraQuanTriNoiDung'),
	(N'SpXoaDuLieuNguyenLieu',        N'SpKiemTraQuanTriNoiDung'),
	(N'SpXoaMonAn',                   N'SpKiemTraQuanTriNoiDung'),
	(N'SpXoaThanhPhanCongThuc',       N'SpKiemTraQuanTriNoiDung'),
	(N'SpXoaVideoHuongDan',           N'SpKiemTraQuanTriNoiDung');


	DECLARE
		@Ten SYSNAME,
		@QuyenMoi SYSNAME,
		@Definition NVARCHAR(MAX);


	DECLARE cur CURSOR LOCAL FAST_FORWARD
	FOR


	SELECT TenProcedure, ProcedureQuyenMoi
	FROM @PhanQuyen;

	OPEN cur;

	FETCH NEXT FROM cur INTO @Ten, @QuyenMoi;

	WHILE @@FETCH_STATUS = 0
	BEGIN

		SET @Definition =
			OBJECT_DEFINITION(OBJECT_ID(N'dbo.' + @Ten));

		IF @Definition IS NULL
		BEGIN
			PRINT N'KHÔNG TỒN TẠI: ' + @Ten;
		END

		ELSE IF @Definition LIKE N'%' + @QuyenMoi + N'%'
		BEGIN
			PRINT N'ĐÃ ĐÚNG: ' + @Ten;
		END

		ELSE IF @Definition LIKE N'%SpKiemTraQuanTri%'
		BEGIN

			/* CREATE -> ALTER */
			SET @Definition =
				REPLACE(
					@Definition,
					N'CREATE PROCEDURE',
					N'ALTER PROCEDURE'
				);

			SET @Definition =
				REPLACE(
					@Definition,
					N'CREATE PROC',
					N'ALTER PROC'
				);

			/* Đổi kiểm tra quyền */
			SET @Definition =
				REPLACE(
					@Definition,
					N'SpKiemTraQuanTri',
					@QuyenMoi
				);

			BEGIN TRY

				EXEC sys.sp_executesql @Definition;

				PRINT N'THÀNH CÔNG: '
					  + @Ten
					  + N' -> '
					  + @QuyenMoi;

			END TRY

			BEGIN CATCH

				PRINT N'LỖI: '
					  + @Ten
					  + N' | '
					  + ERROR_MESSAGE();

			END CATCH;

		END

		ELSE
		BEGIN
			PRINT N'KHÔNG TÌM THẤY KIỂM TRA QUYỀN: ' + @Ten;
		END;


		FETCH NEXT FROM cur INTO @Ten, @QuyenMoi;
	END;


	CLOSE cur;
	DEALLOCATE cur;
	GO
	USE QuanLyThucDon;
	GO
	USE QuanLyThucDon;
	GO
	USE QuanLyThucDon;
	GO
	/* ============================================================
	   1. KIỂM TRA QUẢN TRỊ CHUNG
	   Giữ lại để tương thích với code cũ.
	   KHÔNG dùng cho nghiệp vụ cần phân biệt quyền.
	   ============================================================ */
	CREATE OR ALTER PROCEDURE dbo.SpKiemTraQuanTri
		@MaQuanTri NVARCHAR(20)
	AS
	BEGIN
		SET NOCOUNT ON;

		IF @MaQuanTri IS NULL
		   OR LEN(LTRIM(RTRIM(
				REPLACE(REPLACE(REPLACE(
					@MaQuanTri,
					NCHAR(9), N' '
				), NCHAR(10), N' '), NCHAR(13), N' ')
		   ))) = 0
		BEGIN
			THROW 51031, N'@MaQuanTri không được để trống.', 1;
		END;

		IF NOT EXISTS
		(
			SELECT 1
			FROM dbo.NguoiDung WITH (HOLDLOCK)
			WHERE MaNguoiDung = @MaQuanTri
			  AND VaiTro IN
			  (
				  N'Quản trị nội dung',
				  N'Quản trị hệ thống'
			  )
			  AND TrangThai = N'Đang hoạt động'
		)
		BEGIN
			THROW 51020,
				  N'Cần tài khoản quản trị đang hoạt động.',
				  1;
		END;
	END;
	GO
	/* ============================================================
	   3. SpLayNguoiDung
	   Chỉ QUẢN TRỊ HỆ THỐNG
	   ============================================================ */
	CREATE OR ALTER PROCEDURE dbo.SpLayNguoiDung
		@MaQuanTri NVARCHAR(20),
		@MaNguoiDung NVARCHAR(20) = NULL
	AS
	BEGIN
		SET NOCOUNT ON;

		IF @MaQuanTri IS NULL
		   OR LEN(LTRIM(RTRIM(@MaQuanTri))) = 0
		BEGIN
			THROW 51200, N'@MaQuanTri không được rỗng.', 1;
		END;


		EXEC dbo.SpKiemTraQuanTriHeThong
			 @MaQuanTri = @MaQuanTri;


		SELECT
			MaNguoiDung,
			HoTen,
			ThuDienTu,
			VaiTro,
			TrangThai
		FROM dbo.NguoiDung
		WHERE @MaNguoiDung IS NULL
		   OR MaNguoiDung = @MaNguoiDung
		ORDER BY MaNguoiDung;
	END;
	GO
	/* ============================================================
	   4. SpDatTrangThaiNguoiDung
	   Chỉ QUẢN TRỊ HỆ THỐNG

	   Bổ sung:
	   - không tự khóa
	   - không khóa QT hệ thống cuối cùng
	   ============================================================ */
	CREATE OR ALTER PROCEDURE dbo.SpDatTrangThaiNguoiDung
		@MaQuanTri NVARCHAR(20),
		@MaNguoiDung NVARCHAR(20),
		@TrangThai NVARCHAR(30)
	AS
	BEGIN
		SET NOCOUNT ON;
		SET XACT_ABORT ON;

		DECLARE @TranBanDau INT = @@TRANCOUNT;

		BEGIN TRY

			IF @TranBanDau = 0
				BEGIN TRANSACTION;
			ELSE
				SAVE TRANSACTION CrudSave;


			IF @MaQuanTri IS NULL
			   OR LEN(LTRIM(RTRIM(@MaQuanTri))) = 0
				THROW 51200, N'@MaQuanTri không được rỗng.', 1;


			IF @MaNguoiDung IS NULL
			   OR LEN(LTRIM(RTRIM(@MaNguoiDung))) = 0
				THROW 51200, N'@MaNguoiDung không được rỗng.', 1;


			IF @TrangThai IS NULL
			   OR LEN(LTRIM(RTRIM(@TrangThai))) = 0
				THROW 51200, N'@TrangThai không được rỗng.', 1;


			/* Chỉ QT hệ thống */
			EXEC dbo.SpKiemTraQuanTriHeThong
				 @MaQuanTri = @MaQuanTri;


			IF @TrangThai NOT IN
			(
				N'Đang hoạt động',
				N'Tạm khóa'
			)
			BEGIN
				THROW 51203,
					  N'Trạng thái tài khoản không hợp lệ.',
					  1;
			END;


			/* Kiểm tra tài khoản đích */
			IF NOT EXISTS
			(
				SELECT 1
				FROM dbo.NguoiDung
				WHERE MaNguoiDung = @MaNguoiDung
			)
			BEGIN
				THROW 51202,
					  N'Không tìm thấy tài khoản.',
					  1;
			END;


			/* Không tự khóa chính mình */
			IF @MaQuanTri = @MaNguoiDung
			   AND @TrangThai = N'Tạm khóa'
			BEGIN
				THROW 51204,
					  N'Không thể tự khóa tài khoản Quản trị hệ thống đang sử dụng.',
					  1;
			END;


			/* Không khóa QT hệ thống hoạt động cuối cùng */
			IF @TrangThai = N'Tạm khóa'
			   AND EXISTS
			   (
				   SELECT 1
				   FROM dbo.NguoiDung
				   WHERE MaNguoiDung = @MaNguoiDung
					 AND VaiTro = N'Quản trị hệ thống'
					 AND TrangThai = N'Đang hoạt động'
			   )
			   AND
			   (
				   SELECT COUNT(*)
				   FROM dbo.NguoiDung
				   WHERE VaiTro = N'Quản trị hệ thống'
					 AND TrangThai = N'Đang hoạt động'
			   ) <= 1
			BEGIN
				THROW 51205,
					  N'Hệ thống phải còn ít nhất một Quản trị hệ thống đang hoạt động.',
					  1;
			END;


			UPDATE dbo.NguoiDung
			SET TrangThai = @TrangThai
			WHERE MaNguoiDung = @MaNguoiDung;


			IF @TranBanDau = 0
				COMMIT TRANSACTION;

		END TRY
		BEGIN CATCH

			IF @TranBanDau = 0
			   AND XACT_STATE() <> 0
				ROLLBACK TRANSACTION;

			ELSE IF @TranBanDau > 0
				 AND XACT_STATE() = 1
				ROLLBACK TRANSACTION CrudSave;

			THROW;

		END CATCH;
	END;
	GO
	USE QuanLyThucDon;
	GO
	SELECT
		o.name AS TenProcedure
	FROM sys.sql_modules sm
	JOIN sys.objects o
		ON sm.object_id = o.object_id
	WHERE o.type IN ('P', 'PC')
	  AND
	  (
		   sm.definition LIKE N'%EXEC dbo.SpKiemTraQuanTri @MaQuanTri%'
		OR sm.definition LIKE N'%EXEC dbo.SpKiemTraQuanTri@MaQuanTri%'
	  )
	ORDER BY o.name;
	GO
	SELECT
		o.name AS TenProcedure,
		sm.definition AS NoiDungProcedure
	FROM sys.sql_modules sm
	JOIN sys.objects o
		ON sm.object_id = o.object_id
	WHERE o.type IN ('P', 'PC')
	  AND
	  (
		   sm.definition LIKE N'%EXEC dbo.SpKiemTraQuanTri @MaQuanTri%'
		OR sm.definition LIKE N'%EXEC dbo.SpKiemTraQuanTri@MaQuanTri%'
	  )
	ORDER BY o.name;
	GO
	USE QuanLyThucDon;
	GO
	SELECT
		o.name AS TenProcedure,

		CASE
			WHEN o.name = N'SpThongKeSuDung'
				THEN N'Quản trị hệ thống'

			ELSE N'Quản trị nội dung'
		END AS QuyenCanChuyen

	FROM sys.sql_modules sm
	JOIN sys.objects o
		ON sm.object_id = o.object_id

	WHERE o.type IN ('P', 'PC')
	  AND
	  (
		   sm.definition LIKE N'%EXEC dbo.SpKiemTraQuanTri @MaQuanTri%'
		OR sm.definition LIKE N'%EXEC dbo.SpKiemTraQuanTri@MaQuanTri%'
	  )

	ORDER BY
		QuyenCanChuyen,
		o.name;
	GO
	USE QuanLyThucDon;
	GO
	DECLARE
		@TenProcedure SYSNAME,
		@Definition NVARCHAR(MAX),
		@DefinitionMoi NVARCHAR(MAX),
		@QuyenMoi NVARCHAR(100),
		@ObjectId INT;

	DECLARE CurPhanQuyen CURSOR LOCAL FAST_FORWARD
	FOR
	SELECT
		o.name
	FROM sys.sql_modules sm
	JOIN sys.objects o
		ON sm.object_id = o.object_id
	WHERE o.type = 'P'
	  AND
	  (
		   sm.definition LIKE N'%EXEC dbo.SpKiemTraQuanTri @MaQuanTri%'
		OR sm.definition LIKE N'%EXEC dbo.SpKiemTraQuanTri@MaQuanTri%'
	  )
	ORDER BY o.name;

	OPEN CurPhanQuyen;

	FETCH NEXT FROM CurPhanQuyen INTO @TenProcedure;

	WHILE @@FETCH_STATUS = 0
	BEGIN
		SET @ObjectId =
			OBJECT_ID(N'dbo.' + QUOTENAME(@TenProcedure));

		SET @Definition = OBJECT_DEFINITION(@ObjectId);

		SET @DefinitionMoi = @Definition;


		/* ================================================
		   XÁC ĐỊNH QUYỀN
		   ================================================ */

		IF @TenProcedure = N'SpThongKeSuDung'
			SET @QuyenMoi = N'SpKiemTraQuanTriHeThong';
		ELSE
			SET @QuyenMoi = N'SpKiemTraQuanTriNoiDung';


		/* ================================================
		   CHỈ THAY CÂU GỌI QUYỀN
		   ================================================ */

		SET @DefinitionMoi =
			REPLACE
			(
				@DefinitionMoi,
				N'EXEC dbo.SpKiemTraQuanTri @MaQuanTri',
				N'EXEC dbo.' + @QuyenMoi + N' @MaQuanTri'
			);


		SET @DefinitionMoi =
			REPLACE
			(
				@DefinitionMoi,
				N'EXEC dbo.SpKiemTraQuanTri@MaQuanTri',
				N'EXEC dbo.' + @QuyenMoi + N' @MaQuanTri'
			);


		/* ================================================
		   CHUYỂN HEADER CREATE -> ALTER

		   Source thực tế của bạn đang là:
		   CREATE   PROCEDURE ...
		   nên không dùng REPLACE chuỗi cố định nữa.
		   ================================================ */

		DECLARE @ViTriProcedure INT;

		SET @ViTriProcedure =
			PATINDEX(N'%PROCEDURE%', UPPER(@DefinitionMoi));

		IF @ViTriProcedure > 0
		BEGIN

			/*
			  Giữ mọi thứ từ PROCEDURE trở đi.
			  Tạo header ALTER mới.
			*/
			SET @DefinitionMoi =
				N'ALTER '
				+ SUBSTRING
				  (
					  @DefinitionMoi,
					  @ViTriProcedure,
					  LEN(@DefinitionMoi)
				  );

			BEGIN TRY

				EXEC sys.sp_executesql @DefinitionMoi;

				PRINT
					N'THÀNH CÔNG: '
					+ @TenProcedure
					+ N' -> '
					+ CASE
						WHEN @QuyenMoi = N'SpKiemTraQuanTriHeThong'
							THEN N'Quản trị hệ thống'
						ELSE N'Quản trị nội dung'
					  END;

			END TRY
			BEGIN CATCH

				PRINT
					N'LỖI: '
					+ @TenProcedure
					+ N' | '
					+ ERROR_MESSAGE();

			END CATCH;

		END
		ELSE
		BEGIN

			PRINT
				N'BỎ QUA - Không xác định được header: '
				+ @TenProcedure;

		END;


		FETCH NEXT FROM CurPhanQuyen
		INTO @TenProcedure;
	END;


	CLOSE CurPhanQuyen;
	DEALLOCATE CurPhanQuyen;
	GO
	UPDATE dbo.NguoiDung
	SET VaiTro = N'Quản trị nội dung'
	WHERE MaNguoiDung = N'ND001'
	  AND VaiTro = N'Quản trị viên';
	GO
	IF NOT EXISTS
	(
		SELECT 1
		FROM dbo.NguoiDung
		WHERE VaiTro = N'Quản trị hệ thống'
	)
	BEGIN

		IF NOT EXISTS
		(
			SELECT 1
			FROM dbo.NguoiDung
			WHERE MaNguoiDung = N'ND005'
			   OR ThuDienTu = N'hethong@thucdon.vn'
		)
		BEGIN

			INSERT INTO dbo.NguoiDung
			(
				MaNguoiDung,
				HoTen,
				ThuDienTu,
				MatKhauBam,
				VaiTro,
				TrangThai
			)
			SELECT
				N'ND005',
				N'Quản trị hệ thống',
				N'hethong@thucdon.vn',
				MatKhauBam,
				N'Quản trị hệ thống',
				N'Đang hoạt động'
			FROM dbo.NguoiDung
			WHERE MaNguoiDung = N'ND001';

		END;

	END;
	GO
	DECLARE @TenConstraint SYSNAME;
	DECLARE @SQL NVARCHAR(MAX);

	SELECT TOP (1)
		@TenConstraint = cc.name
	FROM sys.check_constraints cc
	WHERE cc.parent_object_id = OBJECT_ID(N'dbo.NguoiDung')
	  AND cc.definition LIKE N'%VaiTro%';

	IF @TenConstraint IS NOT NULL
	BEGIN
		SET @SQL =
			N'ALTER TABLE dbo.NguoiDung DROP CONSTRAINT '
			+ QUOTENAME(@TenConstraint) + N';';

		EXEC sys.sp_executesql @SQL;
	END;
	GO
	ALTER TABLE dbo.NguoiDung
	WITH CHECK
	ADD CONSTRAINT CK_NguoiDung_VaiTro
	CHECK
	(
		VaiTro IN
		(
			N'Người dùng',
			N'Quản trị nội dung',
			N'Quản trị hệ thống'
		)
	);
	GO
	ALTER TABLE dbo.NguoiDung
	CHECK CONSTRAINT CK_NguoiDung_VaiTro;
	GO
	USE QuanLyThucDon;
	GO
	/* ============================================================
	   1. KIỂM TRA TRƯỚC KHI ĐỔI CONSTRAINT
	   ============================================================ */

	IF EXISTS
	(
		SELECT 1
		FROM dbo.NguoiDung
		WHERE VaiTro NOT IN
		(
			N'Người dùng',
			N'Quản trị nội dung',
			N'Quản trị hệ thống'
		)
	)
	BEGIN
		THROW 51300,
			  N'Vẫn còn tài khoản có vai trò cũ hoặc không hợp lệ. Chưa thể cập nhật constraint.',
			  1;
	END;
	GO
	/* ============================================================
	   2. XÓA CONSTRAINT VAI TRÒ HIỆN TẠI
	   ============================================================ */

	IF EXISTS
	(
		SELECT 1
		FROM sys.check_constraints
		WHERE name = N'CK_NguoiDung_VaiTro'
		  AND parent_object_id = OBJECT_ID(N'dbo.NguoiDung')
	)
	BEGIN
		ALTER TABLE dbo.NguoiDung
		DROP CONSTRAINT CK_NguoiDung_VaiTro;

		PRINT N'Đã xóa CK_NguoiDung_VaiTro cũ.';
	END;
	GO
	/* Constraint cũ ban đầu của DB nếu vẫn còn */
	IF EXISTS
	(
		SELECT 1
		FROM sys.check_constraints
		WHERE name = N'KiemTraVaiTroNguoiDung'
		  AND parent_object_id = OBJECT_ID(N'dbo.NguoiDung')
	)
	BEGIN
		ALTER TABLE dbo.NguoiDung
		DROP CONSTRAINT KiemTraVaiTroNguoiDung;

		PRINT N'Đã xóa KiemTraVaiTroNguoiDung cũ.';
	END;
	GO
	/* ============================================================
	   3. TẠO CONSTRAINT CHÍNH THỨC
	   CHỈ CHO PHÉP ĐÚNG 3 VAI TRÒ
