	/* ============================================================
	   Tạo SEQUENCE bắt đầu sau mã CT lớn nhất hiện tại
	   ============================================================ */

	IF OBJECT_ID(N'dbo.SeqMaCongThuc', N'SO') IS NULL
	BEGIN
		DECLARE @SoBatDau INT;

		SELECT @SoBatDau =
			ISNULL
			(
				MAX
				(
					CASE
						WHEN LEFT(MaCongThuc, 2) = N'CT'
						 AND SUBSTRING(MaCongThuc, 3, 18) NOT LIKE N'%[^0-9]%'
						THEN TRY_CONVERT(INT, SUBSTRING(MaCongThuc, 3, 18))
					END
				),
				0
			) + 1
		FROM dbo.CongThuc;

		DECLARE @SQL NVARCHAR(MAX);

		SET @SQL =
			N'CREATE SEQUENCE dbo.SeqMaCongThuc
			  AS INT
			  START WITH ' + CONVERT(NVARCHAR(20), @SoBatDau) + N'
			  INCREMENT BY 1
			  MINVALUE 1
			  NO CYCLE;';

		EXEC sys.sp_executesql @SQL;
	END;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpCapMaCongThucMoi
		@MaQuanTri NVARCHAR(20)
	AS
	BEGIN
		SET NOCOUNT ON;

		EXEC dbo.SpKiemTraQuanTriNoiDung
			@MaQuanTri = @MaQuanTri;

		DECLARE @So INT;
		DECLARE @MaCongThuc NVARCHAR(20);

		WHILE 1 = 1
		BEGIN
			SET @So = NEXT VALUE FOR dbo.SeqMaCongThuc;

			SET @MaCongThuc =
				N'CT' +
				CASE
					WHEN @So < 1000
						THEN RIGHT(N'000' + CONVERT(NVARCHAR(20), @So), 3)
					ELSE CONVERT(NVARCHAR(20), @So)
				END;

			IF NOT EXISTS
			(
				SELECT 1
				FROM dbo.CongThuc
				WHERE MaCongThuc = @MaCongThuc
			)
				BREAK;
		END;

		SELECT @MaCongThuc AS MaCongThuc;
	END;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpLuuCongThuc
		@MaQuanTri NVARCHAR(20),
		@MaCongThuc NVARCHAR(20),
		@MaMonAn NVARCHAR(20),
		@SoKhauPhanChuan INT,
		@MoTa NVARCHAR(1000) = NULL
	AS
	BEGIN
		SET NOCOUNT ON;
		SET XACT_ABORT ON;

		DECLARE @TranBanDau INT = @@TRANCOUNT;

		BEGIN TRY

			IF @TranBanDau = 0
				BEGIN TRANSACTION;
			ELSE
				SAVE TRANSACTION ProcSave;


			/* ===== Phân quyền ===== */

			EXEC dbo.SpKiemTraQuanTriNoiDung
				@MaQuanTri = @MaQuanTri;


			/* ===== Validate ===== */

			IF @MaCongThuc IS NULL
			   OR LEN(LTRIM(RTRIM(@MaCongThuc))) = 0
			BEGIN
				THROW 51031,
				N'@MaCongThuc không được để trống.',
				1;
			END;


			IF LEFT(@MaCongThuc, 2) <> N'CT'
			   OR LEN(@MaCongThuc) <= 2
			   OR SUBSTRING(@MaCongThuc, 3, 18) LIKE N'%[^0-9]%'
			BEGIN
				THROW 52010,
				N'Mã công thức không hợp lệ. Mã phải có dạng CT001, CT002, CT003...',
				1;
			END;


			IF @MaMonAn IS NULL
			   OR LEN(LTRIM(RTRIM(@MaMonAn))) = 0
			BEGIN
				THROW 51031,
				N'@MaMonAn không được để trống.',
				1;
			END;


			IF @SoKhauPhanChuan IS NULL
			   OR @SoKhauPhanChuan <= 0
			BEGIN
				THROW 52011,
				N'Số khẩu phần chuẩn phải lớn hơn 0.',
				1;
			END;


			IF NOT EXISTS
			(
				SELECT 1
				FROM dbo.MonAn
				WHERE MaMonAn = @MaMonAn
			)
			BEGIN
				THROW 52012,
				N'Món ăn không tồn tại.',
				1;
			END;


			/* Một món chỉ có một công thức */

			IF EXISTS
			(
				SELECT 1
				FROM dbo.CongThuc
				WHERE MaMonAn = @MaMonAn
				  AND MaCongThuc <> @MaCongThuc
			)
			BEGIN
				THROW 52013,
				N'Món ăn này đã có công thức.',
				1;
			END;


			/* Không cho một mã CT thuộc hai món */

			IF EXISTS
			(
				SELECT 1
				FROM dbo.CongThuc WITH (UPDLOCK, HOLDLOCK)
				WHERE MaCongThuc = @MaCongThuc
				  AND MaMonAn <> @MaMonAn
			)
			BEGIN
				THROW 51021,
				N'Mã công thức đã thuộc món ăn khác.',
				1;
			END;


			/* ===== UPDATE / INSERT ===== */

			IF EXISTS
			(
				SELECT 1
				FROM dbo.CongThuc
				WHERE MaCongThuc = @MaCongThuc
			)
			BEGIN

				UPDATE dbo.CongThuc
				SET
					SoKhauPhanChuan = @SoKhauPhanChuan,
					MoTa = @MoTa
				WHERE MaCongThuc = @MaCongThuc;

			END
			ELSE
			BEGIN

				INSERT INTO dbo.CongThuc
				(
					MaCongThuc,
					MaMonAn,
					SoKhauPhanChuan,
					MoTa
				)
				VALUES
				(
					@MaCongThuc,
					@MaMonAn,
					@SoKhauPhanChuan,
					@MoTa
				);

			END;


			IF @TranBanDau = 0
				COMMIT TRANSACTION;


			/* Backend lấy lại mã này */
			SELECT
				@MaCongThuc AS MaCongThuc;

		END TRY
		BEGIN CATCH

			IF @TranBanDau = 0
			   AND XACT_STATE() <> 0
				ROLLBACK TRANSACTION;

			ELSE IF @TranBanDau > 0
				AND XACT_STATE() = 1
				ROLLBACK TRANSACTION ProcSave;

			THROW;

		END CATCH;
	END;
	GO
	USE QuanLyThucDon;
	GO
	SET NOCOUNT ON;
	SET XACT_ABORT ON;
	GO
	/* ============================================================
	   FIX DỨT ĐIỂM MIGRATION MÃ
	   - xử lý UUID
	   - xử lý CTAUTO / TPAUTO / BCAUTO
	   - xử lý mã sai format ở các bảng khác
	   - giữ nguyên mã chuẩn đang có
	   - cập nhật toàn bộ FK
	   - tạm tắt trigger bảo vệ trong lúc migration
	   ============================================================ */


	/* ============================================================
	   1. BẢNG QUY ƯỚC MÃ
	   ============================================================ */

	IF OBJECT_ID(N'dbo.QuyUocMaHeThong', N'U') IS NULL
	BEGIN
		CREATE TABLE dbo.QuyUocMaHeThong
		(
			LoaiMa      SYSNAME      NOT NULL PRIMARY KEY,
			TenBang     SYSNAME      NOT NULL,
			TenCot      SYSNAME      NOT NULL,
			TienTo      NVARCHAR(10) NOT NULL,
			SoHienTai   BIGINT       NOT NULL
				CONSTRAINT DF_QuyUocMa_SoHienTai DEFAULT 0,

			CONSTRAINT UQ_QuyUocMa_BangCot
				UNIQUE(TenBang, TenCot),

			CONSTRAINT CK_QuyUocMa_SoHienTai
				CHECK(SoHienTai >= 0)
		);
	END;
	GO
	/* ============================================================
	   2. ĐỒNG BỘ QUY ƯỚC
	   ============================================================ */

	DECLARE @Q TABLE
	(
		LoaiMa SYSNAME PRIMARY KEY,
		TenBang SYSNAME,
		TenCot SYSNAME,
		TienTo NVARCHAR(10)
	);

	INSERT INTO @Q
	VALUES
	(N'NguoiDung',               N'NguoiDung',               N'MaNguoiDung',        N'ND'),
	(N'KhauVi',                  N'KhauVi',                  N'MaKhauVi',           N'KV'),
	(N'CheDoAn',                 N'CheDoAn',                 N'MaCheDoAn',          N'CDA'),
	(N'SoThichKhauVi',           N'SoThichKhauVi',           N'MaSoThichKhauVi',    N'STKV'),
	(N'CheDoAnNguoiDung',        N'CheDoAnNguoiDung',        N'MaCheDoAnNguoiDung', N'CDND'),
	(N'NganSachAnUong',          N'NganSachAnUong',          N'MaNganSach',         N'NS'),
	(N'MucTieuDinhDuong',        N'MucTieuDinhDuong',        N'MaMucTieu',          N'MT'),

	(N'DonViTinh',               N'DonViTinh',               N'MaDonVi',            N'DVT'),
	(N'NguyenLieu',              N'NguyenLieu',              N'MaNguyenLieu',       N'NL'),
	(N'QuyDoiDonViNguyenLieu',   N'QuyDoiDonViNguyenLieu',   N'MaQuyDoi',           N'QD'),
	(N'NguyenLieuThayThe',       N'NguyenLieuThayThe',       N'MaThayThe',          N'TT'),
	(N'NguyenLieuHienCo',        N'NguyenLieuHienCo',        N'MaChiTiet',          N'NLHC'),
	(N'GiaNguyenLieu',           N'GiaNguyenLieu',           N'MaGia',              N'GIA'),
	(N'ThongTinDinhDuong',       N'ThongTinDinhDuong',       N'MaThongTin',         N'DD'),

	(N'DanhMucMonAn',            N'DanhMucMonAn',            N'MaDanhMuc',          N'DM'),
	(N'MonAn',                   N'MonAn',                   N'MaMonAn',            N'MA'),
	(N'KhauViMonAn',             N'KhauViMonAn',             N'MaKhauViMonAn',      N'KVMA'),
	(N'CheDoAnMonAn',            N'CheDoAnMonAn',            N'MaCheDoAnMonAn',     N'CDMA'),
	(N'MonYeuThich',             N'MonYeuThich',             N'MaMonYeuThich',      N'MYT'),

	(N'CongThuc',                N'CongThuc',                N'MaCongThuc',         N'CT'),
	(N'ThanhPhanCongThuc',       N'ThanhPhanCongThuc',       N'MaThanhPhan',        N'TP'),
	(N'BuocCheBien',             N'BuocCheBien',             N'MaBuoc',             N'BCB'),
	(N'DoanPhimHuongDan',        N'DoanPhimHuongDan',        N'MaDoanPhim',         N'DP'),

	(N'ThucDon',                 N'ThucDon',                 N'MaThucDon',          N'TD'),
	(N'ChiTietThucDon',          N'ChiTietThucDon',          N'MaChiTiet',          N'CTTD'),
	(N'DanhGiaMonAn',            N'DanhGiaMonAn',            N'MaDanhGia',          N'DGMA'),

	(N'DanhGiaDinhDuongThucDon', N'DanhGiaDinhDuongThucDon', N'MaDanhGia',          N'DGTD'),
	(N'PhanHoiCheBien',          N'PhanHoiCheBien',          N'MaPhanHoi',          N'PHCB');


	UPDATE q
	SET
		q.TenBang = x.TenBang,
		q.TenCot  = x.TenCot,
		q.TienTo  = x.TienTo
	FROM dbo.QuyUocMaHeThong q
	JOIN @Q x
	  ON x.LoaiMa = q.LoaiMa;


	INSERT dbo.QuyUocMaHeThong
	(
		LoaiMa,
		TenBang,
		TenCot,
		TienTo,
		SoHienTai
	)
	SELECT
		x.LoaiMa,
		x.TenBang,
		x.TenCot,
		x.TienTo,
		0
	FROM @Q x
	WHERE NOT EXISTS
	(
		SELECT 1
		FROM dbo.QuyUocMaHeThong q
		WHERE q.LoaiMa = x.LoaiMa
	);
	GO
	/* ============================================================
	   3. PROCEDURE MIGRATION 1 BẢNG
	   ============================================================ */

	CREATE OR ALTER PROCEDURE dbo.SpChuanHoaMaMigration
		@TenBang SYSNAME,
		@TenCot SYSNAME,
		@TienTo NVARCHAR(10)
	AS
	BEGIN
		SET NOCOUNT ON;

		DECLARE @ObjectId INT =
			OBJECT_ID(N'dbo.' + QUOTENAME(@TenBang), N'U');

		IF @ObjectId IS NULL
			RETURN;

		IF NOT EXISTS
		(
			SELECT 1
			FROM sys.columns
			WHERE object_id = @ObjectId
			  AND name = @TenCot
		)
			RETURN;


		CREATE TABLE #Map
		(
			MaCu  NVARCHAR(20) NOT NULL PRIMARY KEY,
			MaMoi NVARCHAR(20) NOT NULL UNIQUE
		);


		DECLARE
			@SQL NVARCHAR(MAX),
			@MaxSo BIGINT = 0;


		/* số lớn nhất của mã chuẩn hiện tại */
		SET @SQL = N'
			SELECT @M =
				ISNULL(MAX(
					TRY_CONVERT(
						BIGINT,
						SUBSTRING(
							' + QUOTENAME(@TenCot) + N',
							LEN(@P) + 1,
							20
						)
					)
				),0)
			FROM dbo.' + QUOTENAME(@TenBang) + N'
			WHERE LEFT(' + QUOTENAME(@TenCot) + N',LEN(@P))=@P
			  AND LEN(' + QUOTENAME(@TenCot) + N')>LEN(@P)
			  AND SUBSTRING(
					' + QUOTENAME(@TenCot) + N',
					LEN(@P)+1,
					20
				  ) COLLATE Latin1_General_100_BIN2
				  NOT LIKE N''%[^0-9]%'';
		';

		EXEC sys.sp_executesql
			@SQL,
			N'@P NVARCHAR(10), @M BIGINT OUTPUT',
			@P=@TienTo,
			@M=@MaxSo OUTPUT;


		/* lập map cho UUID / AUTO / mã sai */
		SET @SQL = N'
			;WITH X AS
			(
				SELECT
					' + QUOTENAME(@TenCot) + N' AS MaCu,
					ROW_NUMBER() OVER(
						ORDER BY ' + QUOTENAME(@TenCot) + N'
					) AS STT
				FROM dbo.' + QUOTENAME(@TenBang) + N'
				WHERE NOT
				(
					LEFT(' + QUOTENAME(@TenCot) + N',LEN(@P))=@P

					AND LEN(' + QUOTENAME(@TenCot) + N')>LEN(@P)

					AND SUBSTRING(
							' + QUOTENAME(@TenCot) + N',
							LEN(@P)+1,
							20
						) COLLATE Latin1_General_100_BIN2
						NOT LIKE N''%[^0-9]%''
				)
			)
			INSERT #Map(MaCu,MaMoi)
			SELECT
				MaCu,
				@P +
				CASE
					WHEN @Base + STT < 1000
						THEN RIGHT(
							N''000'' +
							CONVERT(NVARCHAR(20),@Base+STT),
							3
						)
					ELSE CONVERT(
							NVARCHAR(20),
							@Base+STT
						 )
				END
			FROM X;
		';

		EXEC sys.sp_executesql
			@SQL,
			N'@P NVARCHAR(10), @Base BIGINT',
			@P=@TienTo,
			@Base=@MaxSo;


		IF NOT EXISTS(SELECT 1 FROM #Map)
			RETURN;


		/* tìm toàn bộ FK trỏ vào PK này */
		CREATE TABLE #FK
		(
			SchemaCon SYSNAME,
			BangCon SYSNAME,
			CotCon SYSNAME,
			TenFK SYSNAME
		);


		INSERT #FK
		SELECT
			SCHEMA_NAME(t.schema_id),
			t.name,
			c.name,
			fk.name
		FROM sys.foreign_keys fk
		JOIN sys.foreign_key_columns fkc
		  ON fkc.constraint_object_id=fk.object_id
		JOIN sys.tables t
		  ON t.object_id=fkc.parent_object_id
		JOIN sys.columns c
		  ON c.object_id=fkc.parent_object_id
		 AND c.column_id=fkc.parent_column_id
		JOIN sys.columns rc
		  ON rc.object_id=fkc.referenced_object_id
		 AND rc.column_id=fkc.referenced_column_id
		WHERE fkc.referenced_object_id=@ObjectId
		  AND rc.name=@TenCot
		  AND fk.is_disabled=0;


		DECLARE
			@SchemaCon SYSNAME,
			@BangCon SYSNAME,
			@CotCon SYSNAME,
			@TenFK SYSNAME;


		/* tắt FK */
		DECLARE FK_OFF CURSOR LOCAL FAST_FORWARD FOR
			SELECT SchemaCon,BangCon,CotCon,TenFK
			FROM #FK;

		OPEN FK_OFF;

		FETCH NEXT FROM FK_OFF
		INTO @SchemaCon,@BangCon,@CotCon,@TenFK;

		WHILE @@FETCH_STATUS=0
		BEGIN
			SET @SQL =
				N'ALTER TABLE ' +
				QUOTENAME(@SchemaCon) + N'.' +
				QUOTENAME(@BangCon) +
				N' NOCHECK CONSTRAINT ' +
				QUOTENAME(@TenFK) + N';';

			EXEC(@SQL);

			FETCH NEXT FROM FK_OFF
			INTO @SchemaCon,@BangCon,@CotCon,@TenFK;
		END;

		CLOSE FK_OFF;
		DEALLOCATE FK_OFF;


		/* đổi PK */
		SET @SQL = N'
			UPDATE p
			SET ' + QUOTENAME(@TenCot) + N'=m.MaMoi
			FROM dbo.' + QUOTENAME(@TenBang) + N' p
			JOIN #Map m
			  ON m.MaCu=p.' + QUOTENAME(@TenCot) + N';
		';

		EXEC(@SQL);


		/* đổi FK ở toàn bộ bảng con */
		DECLARE FK_UPDATE CURSOR LOCAL FAST_FORWARD FOR
			SELECT SchemaCon,BangCon,CotCon,TenFK
			FROM #FK;

		OPEN FK_UPDATE;

		FETCH NEXT FROM FK_UPDATE
		INTO @SchemaCon,@BangCon,@CotCon,@TenFK;

		WHILE @@FETCH_STATUS=0
		BEGIN
			SET @SQL = N'
				UPDATE c
				SET ' + QUOTENAME(@CotCon) + N'=m.MaMoi
				FROM ' +
				QUOTENAME(@SchemaCon) + N'.' +
				QUOTENAME(@BangCon) + N' c
				JOIN #Map m
				  ON m.MaCu=c.' + QUOTENAME(@CotCon) + N';
			';

			EXEC(@SQL);

			FETCH NEXT FROM FK_UPDATE
			INTO @SchemaCon,@BangCon,@CotCon,@TenFK;
		END;

		CLOSE FK_UPDATE;
		DEALLOCATE FK_UPDATE;


		/* bật lại FK + validate */
		DECLARE FK_ON CURSOR LOCAL FAST_FORWARD FOR
			SELECT SchemaCon,BangCon,CotCon,TenFK
			FROM #FK;

		OPEN FK_ON;

		FETCH NEXT FROM FK_ON
		INTO @SchemaCon,@BangCon,@CotCon,@TenFK;

		WHILE @@FETCH_STATUS=0
		BEGIN
			SET @SQL =
				N'ALTER TABLE ' +
				QUOTENAME(@SchemaCon) + N'.' +
				QUOTENAME(@BangCon) +
				N' WITH CHECK CHECK CONSTRAINT ' +
				QUOTENAME(@TenFK) + N';';

			EXEC(@SQL);

			FETCH NEXT FROM FK_ON
			INTO @SchemaCon,@BangCon,@CotCon,@TenFK;
		END;

		CLOSE FK_ON;
		DEALLOCATE FK_ON;
	END;
	GO
	/* ============================================================
	   4. LƯU DANH SÁCH TRIGGER ĐANG BẬT
	   ============================================================ */

	IF OBJECT_ID('tempdb..#TriggerDangBat') IS NOT NULL
		DROP TABLE #TriggerDangBat;

	SELECT
		SCHEMA_NAME(t.schema_id) AS SchemaName,
		t.name AS TableName,
		tr.name AS TriggerName
	INTO #TriggerDangBat
	FROM sys.triggers tr
	JOIN sys.tables t
	  ON t.object_id=tr.parent_id
	WHERE tr.parent_class=1
	  AND tr.is_disabled=0;
	GO
	/* ============================================================
	   5. MIGRATION TOÀN BỘ
	   ============================================================ */

	BEGIN TRY

		BEGIN TRANSACTION;


		/* --------------------------------------------
		   tạm tắt trigger đang bật
		   -------------------------------------------- */

		DECLARE @SQLTrigger NVARCHAR(MAX)=N'';

		SELECT @SQLTrigger =
			@SQLTrigger +
			N'DISABLE TRIGGER ' +
			QUOTENAME(TriggerName) +
			N' ON ' +
			QUOTENAME(SchemaName) + N'.' +
			QUOTENAME(TableName) + N';' +
			CHAR(13)
		FROM #TriggerDangBat;

		EXEC(@SQLTrigger);


		/* --------------------------------------------
		   chuẩn hóa tất cả mã
		   -------------------------------------------- */

		DECLARE
			@Loai SYSNAME,
			@Bang SYSNAME,
			@Cot SYSNAME,
			@Prefix NVARCHAR(10);


		DECLARE MA_CURSOR CURSOR LOCAL FAST_FORWARD FOR
		SELECT
			LoaiMa,
			TenBang,
			TenCot,
			TienTo
		FROM dbo.QuyUocMaHeThong
		ORDER BY
			CASE LoaiMa
				WHEN N'NguoiDung' THEN 1
				WHEN N'KhauVi' THEN 2
				WHEN N'CheDoAn' THEN 3
				WHEN N'DonViTinh' THEN 4
				WHEN N'NguyenLieu' THEN 5
				WHEN N'DanhMucMonAn' THEN 6
				WHEN N'MonAn' THEN 7
				WHEN N'CongThuc' THEN 8
				WHEN N'ThanhPhanCongThuc' THEN 9
				WHEN N'BuocCheBien' THEN 10
				WHEN N'DoanPhimHuongDan' THEN 11
				WHEN N'ThucDon' THEN 12
				WHEN N'ChiTietThucDon' THEN 13
				ELSE 100
			END,
			LoaiMa;


		OPEN MA_CURSOR;

		FETCH NEXT FROM MA_CURSOR
		INTO @Loai,@Bang,@Cot,@Prefix;


		WHILE @@FETCH_STATUS=0
		BEGIN

			EXEC dbo.SpChuanHoaMaMigration
				@TenBang=@Bang,
				@TenCot=@Cot,
				@TienTo=@Prefix;

			FETCH NEXT FROM MA_CURSOR
			INTO @Loai,@Bang,@Cot,@Prefix;
		END;


		CLOSE MA_CURSOR;
		DEALLOCATE MA_CURSOR;


		/* --------------------------------------------
		   bật lại đúng những trigger ban đầu đang bật
		   -------------------------------------------- */

		SET @SQLTrigger=N'';

		SELECT @SQLTrigger =
			@SQLTrigger +
			N'ENABLE TRIGGER ' +
			QUOTENAME(TriggerName) +
			N' ON ' +
			QUOTENAME(SchemaName) + N'.' +
			QUOTENAME(TableName) + N';' +
			CHAR(13)
		FROM #TriggerDangBat;

		EXEC(@SQLTrigger);


		/* --------------------------------------------
		   đồng bộ bộ đếm
		   -------------------------------------------- */

		DECLARE
			@M BIGINT,
			@SQL NVARCHAR(MAX);


		DECLARE COUNTER_CURSOR CURSOR LOCAL FAST_FORWARD FOR
		SELECT LoaiMa,TenBang,TenCot,TienTo
		FROM dbo.QuyUocMaHeThong;


		OPEN COUNTER_CURSOR;

		FETCH NEXT FROM COUNTER_CURSOR
		INTO @Loai,@Bang,@Cot,@Prefix;


		WHILE @@FETCH_STATUS=0
		BEGIN

			IF OBJECT_ID(N'dbo.'+@Bang,N'U') IS NOT NULL
			BEGIN

				SET @M=0;

				SET @SQL=N'
					SELECT @MaxOut =
						ISNULL(MAX(
							TRY_CONVERT(
								BIGINT,
								SUBSTRING(
									'+QUOTENAME(@Cot)+N',
									LEN(@P)+1,
									20
								)
							)
						),0)
					FROM dbo.'+QUOTENAME(@Bang)+N'
					WHERE LEFT('+QUOTENAME(@Cot)+N',LEN(@P))=@P
					  AND LEN('+QUOTENAME(@Cot)+N')>LEN(@P)
					  AND SUBSTRING(
							'+QUOTENAME(@Cot)+N',
							LEN(@P)+1,
							20
						  ) COLLATE Latin1_General_100_BIN2
						  NOT LIKE N''%[^0-9]%'';
				';

				EXEC sys.sp_executesql
					@SQL,
					N'@P NVARCHAR(10),@MaxOut BIGINT OUTPUT',
					@P=@Prefix,
					@MaxOut=@M OUTPUT;


				UPDATE dbo.QuyUocMaHeThong
				SET SoHienTai=@M
				WHERE LoaiMa=@Loai;

			END;


			FETCH NEXT FROM COUNTER_CURSOR
			INTO @Loai,@Bang,@Cot,@Prefix;

		END;


		CLOSE COUNTER_CURSOR;
		DEALLOCATE COUNTER_CURSOR;


		COMMIT TRANSACTION;

	END TRY
	BEGIN CATCH

		IF CURSOR_STATUS('local','MA_CURSOR')>=0
			CLOSE MA_CURSOR;

		IF CURSOR_STATUS('local','MA_CURSOR')>-3
			DEALLOCATE MA_CURSOR;

		IF CURSOR_STATUS('local','COUNTER_CURSOR')>=0
			CLOSE COUNTER_CURSOR;

		IF CURSOR_STATUS('local','COUNTER_CURSOR')>-3
			DEALLOCATE COUNTER_CURSOR;


		IF XACT_STATE()<>0
			ROLLBACK TRANSACTION;


		/* bảo đảm trigger được bật lại */
		DECLARE @Restore NVARCHAR(MAX)=N'';

		SELECT @Restore =
			@Restore +
			N'ENABLE TRIGGER ' +
			QUOTENAME(TriggerName) +
			N' ON ' +
			QUOTENAME(SchemaName)+N'.'+
			QUOTENAME(TableName)+N';'+
			CHAR(13)
		FROM #TriggerDangBat;

		BEGIN TRY
			EXEC(@Restore);
		END TRY
		BEGIN CATCH
		END CATCH;


		THROW;
	END CATCH;
	GO
	/* ============================================================
	   6. XÓA CHECK MÃ TỪ LẦN CHẠY LỖI TRƯỚC
	   ============================================================ */

	DECLARE @DropCheck NVARCHAR(MAX)=N'';

	SELECT @DropCheck =
		@DropCheck +
		N'ALTER TABLE ' +
		QUOTENAME(SCHEMA_NAME(t.schema_id)) + N'.' +
		QUOTENAME(t.name) +
		N' DROP CONSTRAINT ' +
		QUOTENAME(c.name) + N';' +
		CHAR(13)
	FROM sys.check_constraints c
	JOIN sys.tables t
	  ON t.object_id=c.parent_object_id
	WHERE c.name LIKE N'CK[_]Ma[_]%';

	IF LEN(@DropCheck)>0
		EXEC(@DropCheck);
	GO
	/* ============================================================
	   7. TẠO LẠI CHECK CHUẨN
	   ============================================================ */

	DECLARE
		@Bang SYSNAME,
		@Cot SYSNAME,
		@Prefix NVARCHAR(10),
		@LenPrefix INT,
		@TenCK SYSNAME,
		@SQL NVARCHAR(MAX);


	DECLARE CK_CURSOR CURSOR LOCAL FAST_FORWARD FOR
	SELECT TenBang,TenCot,TienTo
	FROM dbo.QuyUocMaHeThong;


	OPEN CK_CURSOR;

	FETCH NEXT FROM CK_CURSOR
	INTO @Bang,@Cot,@Prefix;


	WHILE @@FETCH_STATUS=0
	BEGIN

		IF OBJECT_ID(N'dbo.'+@Bang,N'U') IS NOT NULL
		BEGIN

			SET @LenPrefix=LEN(@Prefix);

			SET @TenCK =
				LEFT(
					N'CK_Ma_'+@Bang+N'_'+@Cot,
					128
				);


			SET @SQL=N'
				ALTER TABLE dbo.'+QUOTENAME(@Bang)+N'
				WITH CHECK
				ADD CONSTRAINT '+QUOTENAME(@TenCK)+N'
				CHECK
				(
					LEFT(
						'+QUOTENAME(@Cot)+N',
						'+CONVERT(NVARCHAR(10),@LenPrefix)+N'
					) =
					N'''+REPLACE(@Prefix,'''','''''')+N'''

					AND

					LEN('+QUOTENAME(@Cot)+N') >
					'+CONVERT(NVARCHAR(10),@LenPrefix)+N'

					AND

					SUBSTRING(
						'+QUOTENAME(@Cot)+N',
						'+CONVERT(NVARCHAR(10),@LenPrefix+1)+N',
						20
					) COLLATE Latin1_General_100_BIN2
					NOT LIKE N''%[^0-9]%''
				);
			';

			EXEC(@SQL);

		END;


		FETCH NEXT FROM CK_CURSOR
		INTO @Bang,@Cot,@Prefix;

	END;


	CLOSE CK_CURSOR;
	DEALLOCATE CK_CURSOR;
	GO

	/* ============================================================
	   9. XÓA HELPER MIGRATION
	   ============================================================ */

	DROP PROCEDURE dbo.SpChuanHoaMaMigration;
	GO
	/* ============================================================
	   10. KIỂM TRA CUỐI CÙNG
	   ============================================================ */

	DECLARE
		@Bang SYSNAME,
		@Cot SYSNAME,
		@Prefix NVARCHAR(10),
		@Loai SYSNAME,
		@SQL NVARCHAR(MAX);


	CREATE TABLE #MaLoi
	(
		LoaiMa SYSNAME,
		TenBang SYSNAME,
		Ma NVARCHAR(100)
	);


	DECLARE AUDIT_CURSOR CURSOR LOCAL FAST_FORWARD FOR
	SELECT
		LoaiMa,
		TenBang,
		TenCot,
		TienTo
	FROM dbo.QuyUocMaHeThong;


	OPEN AUDIT_CURSOR;

	FETCH NEXT FROM AUDIT_CURSOR
	INTO @Loai,@Bang,@Cot,@Prefix;


	WHILE @@FETCH_STATUS=0
	BEGIN

		IF OBJECT_ID(N'dbo.'+@Bang,N'U') IS NOT NULL
		BEGIN

			SET @SQL=N'
				INSERT #MaLoi
				(
					LoaiMa,
					TenBang,
					Ma
				)
				SELECT
					@L,
					@B,
					CONVERT(
						NVARCHAR(100),
						'+QUOTENAME(@Cot)+N'
					)
				FROM dbo.'+QUOTENAME(@Bang)+N'
				WHERE NOT
				(
					LEFT(
						'+QUOTENAME(@Cot)+N',
						LEN(@P)
					)=@P

					AND

					LEN('+QUOTENAME(@Cot)+N')>LEN(@P)

					AND

					SUBSTRING(
						'+QUOTENAME(@Cot)+N',
						LEN(@P)+1,
						20
					) COLLATE Latin1_General_100_BIN2
					NOT LIKE N''%[^0-9]%''
				);
			';


			EXEC sys.sp_executesql
				@SQL,
				N'@L SYSNAME,@B SYSNAME,@P NVARCHAR(10)',
				@L=@Loai,
				@B=@Bang,
				@P=@Prefix;

		END;


		FETCH NEXT FROM AUDIT_CURSOR
		INTO @Loai,@Bang,@Cot,@Prefix;

	END;


	CLOSE AUDIT_CURSOR;
	DEALLOCATE AUDIT_CURSOR;


	/* KẾT QUẢ NÀY PHẢI 0 DÒNG */
	SELECT *
	FROM #MaLoi
	ORDER BY TenBang,Ma;


	/* XEM TOÀN BỘ MÃ TIẾP THEO */
	SELECT
		LoaiMa,
		TenBang,
		TienTo,
		SoHienTai,

		TienTo +
		CASE
			WHEN SoHienTai+1<1000
				THEN RIGHT(
					N'000'+
					CONVERT(
						NVARCHAR(20),
						SoHienTai+1
					),
					3
				)
			ELSE
				CONVERT(
					NVARCHAR(20),
					SoHienTai+1
				)
		END AS MaTiepTheo

	FROM dbo.QuyUocMaHeThong
	ORDER BY LoaiMa;


	USE QuanLyThucDon;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpKiemTraMonAnCongKhai
		@MaMonAn NVARCHAR(20)
	AS
	BEGIN
		SET NOCOUNT ON;

		IF @MaMonAn IS NULL
		   OR LEN(LTRIM(RTRIM(@MaMonAn))) = 0
			THROW 51031, N'@MaMonAn không được để trống.', 1;

		IF NOT EXISTS (
			SELECT 1
			FROM dbo.MonAn m
			JOIN dbo.DanhMucMonAn dm
			  ON dm.MaDanhMuc = m.MaDanhMuc
			WHERE m.MaMonAn = @MaMonAn
			  AND m.TrangThaiHienThi = N'Hiển thị'
			  AND dm.TrangThaiSuDung = N'Đang sử dụng'
		)
			THROW 50006, N'Món ăn không tồn tại hoặc hiện không được hiển thị.', 1;

		IF NOT EXISTS (
			SELECT 1
			FROM dbo.CongThuc
			WHERE MaMonAn = @MaMonAn
			  AND DaCongBo = 1
		)
			THROW 51005, N'Món chưa có công thức được công bố.', 1;
	END;
	GO
	USE QuanLyThucDon;
	GO
	CREATE OR ALTER PROCEDURE dbo.SpLuuVideoHuongDan
		@MaQuanTri NVARCHAR(20),
		@MaDoanPhim NVARCHAR(20) = NULL OUTPUT,
		@MaCongThuc NVARCHAR(20),
		@TieuDe NVARCHAR(200),
		@DuongDan NVARCHAR(500),
		@MoTa NVARCHAR(500) = NULL,
		@ThoiLuong INT = NULL,
		@TrangThaiSuDung NVARCHAR(30) = N'Đang sử dụng'
	AS
	BEGIN
		SET NOCOUNT ON;
		SET XACT_ABORT ON;

		DECLARE @TranBanDau INT = @@TRANCOUNT;
		DECLARE @LaThemMoiTuDong BIT = 0;

		BEGIN TRY
			IF @TranBanDau = 0
				BEGIN TRANSACTION;
			ELSE
				SAVE TRANSACTION SpLuuVideoSave;

			-- 1. Kiểm tra dữ liệu đầu vào
			IF NULLIF(LTRIM(RTRIM(@MaQuanTri)), N'') IS NULL
				THROW 51031, N'Mã quản trị không được để trống.', 1;

			IF NULLIF(LTRIM(RTRIM(@MaCongThuc)), N'') IS NULL
				THROW 51031, N'Mã công thức không được để trống.', 1;

			IF NULLIF(LTRIM(RTRIM(@TieuDe)), N'') IS NULL
				THROW 51031, N'Tiêu đề video không được để trống.', 1;

			IF NULLIF(LTRIM(RTRIM(@DuongDan)), N'') IS NULL
				THROW 51031, N'Đường dẫn video không được để trống.', 1;

			IF @ThoiLuong IS NOT NULL AND @ThoiLuong <= 0
				THROW 51215, N'Thời lượng video phải lớn hơn 0 giây.', 1;

			IF @TrangThaiSuDung IS NULL
			   OR @TrangThaiSuDung NOT IN
				  (N'Đang sử dụng', N'Ngừng sử dụng')
				THROW 51216, N'Trạng thái video không hợp lệ.', 1;

			-- 2. Kiểm tra quyền quản trị nội dung
			EXEC dbo.SpKiemTraQuanTriNoiDung
				@MaQuanTri = @MaQuanTri;

			-- 3. Kiểm tra công thức
			IF NOT EXISTS (
				SELECT 1
				FROM dbo.CongThuc
				WHERE MaCongThuc = @MaCongThuc
			)
				THROW 51217, N'Công thức không tồn tại.', 1;

			-- 4. Kiểm tra URL HTTPS
			SET @DuongDan = LTRIM(RTRIM(@DuongDan));

			IF @DuongDan NOT LIKE N'https://%_%'
				THROW 51029, N'Video cần URL HTTPS.', 1;

			-- 5. Nếu không truyền mã video thì tự cấp mã mới
			SET @MaDoanPhim =
				NULLIF(LTRIM(RTRIM(@MaDoanPhim)), N'');

			IF @MaDoanPhim IS NULL
			BEGIN
				SET @LaThemMoiTuDong = 1;

				EXEC dbo.SpCapMaMoi
					@LoaiMa = N'DoanPhimHuongDan',
					@MaMoi = @MaDoanPhim OUTPUT;

				IF NULLIF(LTRIM(RTRIM(@MaDoanPhim)), N'') IS NULL
					THROW 51218, N'Không thể cấp mã video mới.', 1;
			END;

			-- 6. Nếu mã đã tồn tại: sửa video
			IF EXISTS (
				SELECT 1
				FROM dbo.DoanPhimHuongDan WITH (UPDLOCK, HOLDLOCK)
				WHERE MaDoanPhim = @MaDoanPhim
			)
			BEGIN
				-- Mã vừa cấp tự động tuyệt đối không được
				-- trùng với một video đang tồn tại.
				IF @LaThemMoiTuDong = 1
					THROW 51219,
						N'Bộ cấp mã video bị trùng. Cần kiểm tra QuyUocMaHeThong.',
						1;

				-- Không cho chuyển video sang công thức khác
				IF EXISTS (
					SELECT 1
					FROM dbo.DoanPhimHuongDan
					WHERE MaDoanPhim = @MaDoanPhim
					  AND MaCongThuc <> @MaCongThuc
				)
					THROW 51032,
						N'Video đã thuộc công thức khác.',
						1;

				UPDATE dbo.DoanPhimHuongDan
				SET
					TieuDe = @TieuDe,
					DuongDan = @DuongDan,
					MoTa = @MoTa,
					ThoiLuong = @ThoiLuong,
					TrangThaiSuDung = @TrangThaiSuDung,
					NgayCapNhat = SYSUTCDATETIME()
				WHERE MaDoanPhim = @MaDoanPhim
				  AND MaCongThuc = @MaCongThuc;
			END
			ELSE
			BEGIN
				-- 7. Mã chưa tồn tại: thêm video mới
				INSERT INTO dbo.DoanPhimHuongDan
				(
					MaDoanPhim,
					MaCongThuc,
					TieuDe,
					DuongDan,
					MoTa,
					ThoiLuong,
					TrangThaiSuDung
				)
				VALUES
				(
					@MaDoanPhim,
					@MaCongThuc,
					@TieuDe,
					@DuongDan,
					@MoTa,
					@ThoiLuong,
					@TrangThaiSuDung
				);
			END;

			IF @TranBanDau = 0
				COMMIT TRANSACTION;
		END TRY
		BEGIN CATCH
			IF @TranBanDau = 0 AND XACT_STATE() <> 0
				ROLLBACK TRANSACTION;
			ELSE IF @TranBanDau > 0 AND XACT_STATE() = 1
				ROLLBACK TRANSACTION SpLuuVideoSave;

			THROW;
		END CATCH;
	END;
	GO
	USE QuanLyThucDon;
	GO
	IF OBJECT_ID(N'dbo.BoSuuTapYeuThich', N'U') IS NULL
	BEGIN
		CREATE TABLE dbo.BoSuuTapYeuThich
		(
			MaBoSuuTap NVARCHAR(20) NOT NULL,
			MaNguoiDung NVARCHAR(20) NOT NULL,
			TenBoSuuTap NVARCHAR(100) NOT NULL,
			MoTa NVARCHAR(500) NULL,

			LaRiengTu BIT NOT NULL
				CONSTRAINT DF_BST_LaRiengTu DEFAULT (1),

			NgayTao DATETIME2(3) NOT NULL
				CONSTRAINT DF_BST_NgayTao DEFAULT (SYSDATETIME()),

			NgayCapNhat DATETIME2(3) NOT NULL
				CONSTRAINT DF_BST_NgayCapNhat DEFAULT (SYSDATETIME()),

			CONSTRAINT PK_BoSuuTapYeuThich
				PRIMARY KEY (MaBoSuuTap),

			CONSTRAINT UQ_BST_MaVaChuSoHuu
				UNIQUE (MaBoSuuTap, MaNguoiDung),

			CONSTRAINT UQ_BST_NguoiDung_Ten
				UNIQUE (MaNguoiDung, TenBoSuuTap),

			CONSTRAINT CK_BST_TenKhongRong
				CHECK (LEN(LTRIM(RTRIM(TenBoSuuTap))) > 0),

			CONSTRAINT FK_BST_NguoiDung
				FOREIGN KEY (MaNguoiDung)
				REFERENCES dbo.NguoiDung(MaNguoiDung)
		);

		CREATE INDEX IX_BST_NguoiDung_NgayTao
		ON dbo.BoSuuTapYeuThich(MaNguoiDung, NgayTao DESC);
	END;
	GO
	IF OBJECT_ID(N'dbo.ChiTietBoSuuTapYeuThich', N'U') IS NULL
	BEGIN
		CREATE TABLE dbo.ChiTietBoSuuTapYeuThich
		(
			MaChiTietBoSuuTap NVARCHAR(20) NOT NULL,
			MaBoSuuTap NVARCHAR(20) NOT NULL,
			MaNguoiDung NVARCHAR(20) NOT NULL,
			MaMonAn NVARCHAR(20) NOT NULL,

			NgayThem DATETIME2(3) NOT NULL
				CONSTRAINT DF_CTBST_NgayThem
				DEFAULT (SYSDATETIME()),

			CONSTRAINT PK_ChiTietBoSuuTapYeuThich
				PRIMARY KEY (MaChiTietBoSuuTap),

			CONSTRAINT UQ_CTBST_BoSuuTap_MonAn
				UNIQUE (MaBoSuuTap, MaMonAn),

			CONSTRAINT FK_CTBST_BoSuuTap
				FOREIGN KEY (MaBoSuuTap, MaNguoiDung)
				REFERENCES dbo.BoSuuTapYeuThich
					(MaBoSuuTap, MaNguoiDung)
				ON DELETE CASCADE,

			CONSTRAINT FK_CTBST_MonYeuThich
				FOREIGN KEY (MaNguoiDung, MaMonAn)
				REFERENCES dbo.MonYeuThich
					(MaNguoiDung, MaMonAn)
				ON DELETE CASCADE
		);

		CREATE INDEX IX_CTBST_ThuTuThem
		ON dbo.ChiTietBoSuuTapYeuThich
			(MaBoSuuTap, NgayThem, MaChiTietBoSuuTap);

		CREATE INDEX IX_CTBST_NguoiDung_MonAn
		ON dbo.ChiTietBoSuuTapYeuThich
			(MaNguoiDung, MaMonAn);
	END;
	GO
	-- CTBST001, CTBST002...
	-- =====================================================

	IF NOT EXISTS (
		SELECT 1
		FROM dbo.QuyUocMaHeThong
		WHERE LoaiMa = N'BoSuuTapYeuThich'
	)
	BEGIN
		INSERT INTO dbo.QuyUocMaHeThong
			(LoaiMa, TenBang, TenCot, TienTo, SoHienTai)
		VALUES
			(
				N'BoSuuTapYeuThich',
				N'BoSuuTapYeuThich',
				N'MaBoSuuTap',
				N'BST',
				0
			);
	END;

	IF NOT EXISTS (
		SELECT 1
		FROM dbo.QuyUocMaHeThong
		WHERE LoaiMa = N'ChiTietBoSuuTapYeuThich'
	)
	BEGIN
		INSERT INTO dbo.QuyUocMaHeThong
			(LoaiMa, TenBang, TenCot, TienTo, SoHienTai)
		VALUES
			(
				N'ChiTietBoSuuTapYeuThich',
				N'ChiTietBoSuuTapYeuThich',
				N'MaChiTietBoSuuTap',
				N'CTBST',
				0
			);
	END;
	GO
