	/* ============================================================
	   PHÂN LOẠI MÓN ĂN: DANH MỤC CHÍNH VÀ NHÃN PHỤ

	   Giữ nguyên món và công thức hiện có. Danh mục cũ được đánh dấu
	   để không dùng cho món nhập mới; việc gán lại danh mục cho từng
	   món sẽ thực hiện khi dữ liệu nguồn được đối chiếu.
	   ============================================================ */

	IF COL_LENGTH(N'dbo.DanhMucMonAn', N'LoaiDanhMuc') IS NULL
	BEGIN
		ALTER TABLE dbo.DanhMucMonAn
			ADD LoaiDanhMuc NVARCHAR(20) NOT NULL
				CONSTRAINT DF_DanhMucMonAn_LoaiDanhMuc DEFAULT (N'Danh mục chính');
	END;
	-- Đảm bảo cột LoaiDanhMuc tồn tại trước khi thao tác
IF NOT EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID(N'dbo.DanhMucMonAn') AND name = N'LoaiDanhMuc')
BEGIN
    ALTER TABLE dbo.DanhMucMonAn ADD LoaiDanhMuc NVARCHAR(100) NULL;
END
GO
-- Thêm cột LoaiDanhMuc nếu chưa có trong bảng DanhMucMonAn
IF NOT EXISTS (SELECT 1 FROM sys.columns WHERE object_id = OBJECT_ID(N'dbo.DanhMucMonAn') AND name = N'LoaiDanhMuc')
BEGIN
    ALTER TABLE dbo.DanhMucMonAn ADD LoaiDanhMuc NVARCHAR(100) NULL;
END
GO
-- (Giữ nguyên phần code gốc của bạn từ đây trở xuống như trong ảnh)
IF NOT EXISTS (
    SELECT 1 FROM sys.check_constraints
    WHERE parent_object_id = OBJECT_ID(N'dbo.DanhMucMonAn')
    AND name = N'CK_DanhMucMonAn_LoaiDanhMuc'
)
BEGIN
    ALTER TABLE dbo.DanhMucMonAn
    ADD CONSTRAINT CK_DanhMucMonAn_LoaiDanhMuc
    CHECK (LoaiDanhMuc IN (N'Danh mục chính', N'Nhãn phụ', N'Danh mục cũ'));
END;
GO

UPDATE dbo.DanhMucMonAn
SET LoaiDanhMuc = N'Danh mục cũ'
