		(
			MaMonAn NVARCHAR(20) NOT NULL,
			MaNhan NVARCHAR(20) NOT NULL,
			CONSTRAINT PK_MonAnNhan PRIMARY KEY (MaMonAn, MaNhan),
			CONSTRAINT FK_MonAnNhan_MonAn FOREIGN KEY (MaMonAn)
				REFERENCES dbo.MonAn(MaMonAn),
			CONSTRAINT FK_MonAnNhan_DanhMuc FOREIGN KEY (MaNhan)
				REFERENCES dbo.DanhMucMonAn(MaDanhMuc)
		);
	END;


