	IF (SELECT COUNT(*) FROM dbo.NguoiDung) <> 9
	BEGIN THROW 55001, N'Seed dữ liệu: số tài khoản không bằng 9.', 1; END;

	IF (SELECT COUNT(*) FROM dbo.MonAn) <> 10
	BEGIN THROW 55002, N'Seed dữ liệu: cần đúng 10 món canh mới.', 1; END;

	IF (SELECT COUNT(*) FROM dbo.CongThuc) <> 10
	BEGIN THROW 55003, N'Seed dữ liệu: cần đúng 10 công thức mới.', 1; END;

	IF (SELECT COUNT(*) FROM dbo.NguyenLieu) <> 143
	BEGIN THROW 55004, N'Seed dữ liệu: số nguyên liệu không bằng 143.', 1; END;

	IF (SELECT COUNT(*) FROM dbo.ThongTinDinhDuong) <> 90
	BEGIN THROW 55005, N'Seed dữ liệu: số bản ghi dinh dưỡng không bằng 90.', 1; END;

	IF (SELECT COUNT(*) FROM dbo.DoanPhimHuongDan) <> 10
	BEGIN THROW 55006, N'Seed dữ liệu: cần đúng 10 video khớp công thức.', 1; END;
	*/
	
	BEGIN TRY
    -- Nếu có transaction đang mở thì tiến hành transaction seed dữ liệu
    IF @@TRANCOUNT = 0
        BEGIN TRANSACTION;

    -------------------------------------------------------------------------
    -- (Giữ nguyên toàn bộ các lệnh INSERT / SEED dữ liệu hiện tại của bạn ở đây)
    -------------------------------------------------------------------------

    IF @@TRANCOUNT > 0
        COMMIT TRANSACTION;
        
    PRINT N'Đã hoàn tất seed dữ liệu thành công!';
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0
        ROLLBACK TRANSACTION;

    DECLARE @ErrMsg NVARCHAR(4000) = ERROR_MESSAGE(), @ErrSeverity INT = ERROR_SEVERITY();
    RAISERROR(@ErrMsg, @ErrSeverity, 1);
END CATCH;
GO

	USE QuanLyThucDon;
	GO

	IF OBJECT_ID(N'dbo.UserPreferences', N'U') IS NULL
	BEGIN
		CREATE TABLE dbo.UserPreferences
		(
			user_id NVARCHAR(20) NOT NULL,
			answers NVARCHAR(MAX) NOT NULL
				CONSTRAINT DF_UserPreferences_answers DEFAULT N'{}',
			completed BIT NOT NULL
				CONSTRAINT DF_UserPreferences_completed DEFAULT 0,
			survey_shown BIT NOT NULL
				CONSTRAINT DF_UserPreferences_shown DEFAULT 0,

			CONSTRAINT PK_UserPreferences
				PRIMARY KEY (user_id),

			CONSTRAINT FK_UserPreferences_User
				FOREIGN KEY (user_id)
				REFERENCES dbo.NguoiDung(MaNguoiDung)
				ON DELETE CASCADE
		);
	END;
	GO

	/* ============================================================
	   PHÂN LOẠI MÓN ĂN: DANH MỤC CHÍNH VÀ NHÃN PHỤ

	   Giữ nguyên món và công thức hiện có. Danh mục cũ được đánh dấu
	   để không dùng cho món nhập mới; việc gán lại danh mục cho từng
	   món sẽ thực hiện khi dữ liệu nguồn được đối chiếu.
	   ============================================================ */

	IF COL_LENGTH(N'dbo.DanhMucMonAn', N'LoaiDanhMuc') IS NULL
	BEGIN
		ALTER TABLE dbo.DanhMucMonAn
			ADD LoaiDanhMuc NVARCHAR(20) NOT NULL
				CONSTRAINT DF_DanhMucMonAn_LoaiDanhMuc DEFAULT (N'Danh mục chính');
	END;
	GO

	IF NOT EXISTS (
		SELECT 1 FROM sys.check_constraints
		WHERE parent_object_id = OBJECT_ID(N'dbo.DanhMucMonAn')
		  AND name = N'CK_DanhMucMonAn_LoaiDanhMuc'
	)
	BEGIN
		ALTER TABLE dbo.DanhMucMonAn
			ADD CONSTRAINT CK_DanhMucMonAn_LoaiDanhMuc
			CHECK (LoaiDanhMuc IN (N'Danh mục chính', N'Nhãn phụ', N'Danh mục cũ'));
	END;
	GO

	UPDATE dbo.DanhMucMonAn
	SET LoaiDanhMuc = N'Danh mục cũ'
	WHERE MaDanhMuc IN (N'DM001',N'DM002',N'DM003',N'DM004',N'DM005',
						N'DM006',N'DM007',N'DM008',N'DM009',N'DM010');

	UPDATE dbo.DanhMucMonAn
	SET LoaiDanhMuc = N'Danh mục chính'
	WHERE MaDanhMuc = N'DM011';
	GO

	DECLARE @DanhMucMoi TABLE
	(
		MaDanhMuc NVARCHAR(20) NOT NULL PRIMARY KEY,
		TenDanhMuc NVARCHAR(100) NOT NULL,
		MoTa NVARCHAR(500) NOT NULL,
		LoaiDanhMuc NVARCHAR(20) NOT NULL
	);

