	INSERT INTO dbo.DanhMucMonAn (MaDanhMuc, TenDanhMuc, MoTa, LoaiDanhMuc)
	SELECT n.MaDanhMuc, n.TenDanhMuc, n.MoTa, n.LoaiDanhMuc
	FROM @DanhMucMoi n
	WHERE NOT EXISTS
	(
		SELECT 1 FROM dbo.DanhMucMonAn d
		WHERE d.MaDanhMuc = n.MaDanhMuc OR d.TenDanhMuc = n.TenDanhMuc
	);
	GO

	IF OBJECT_ID(N'dbo.MonAnNhan', N'U') IS NULL
	BEGIN
		CREATE TABLE dbo.MonAnNhan
		(
			MaMonAn NVARCHAR(20) NOT NULL,
			MaNhan NVARCHAR(20) NOT NULL,
			CONSTRAINT PK_MonAnNhan PRIMARY KEY (MaMonAn, MaNhan),
			CONSTRAINT FK_MonAnNhan_MonAn FOREIGN KEY (MaMonAn)
				REFERENCES dbo.MonAn(MaMonAn),
			CONSTRAINT FK_MonAnNhan_DanhMuc FOREIGN KEY (MaNhan)
				REFERENCES dbo.DanhMucMonAn(MaDanhMuc)
		);
	END;
	GO

	IF NOT EXISTS (SELECT 1 FROM sys.indexes WHERE object_id=OBJECT_ID(N'dbo.MonAnNhan') AND name=N'IX_MonAnNhan_MaNhan')
		CREATE INDEX IX_MonAnNhan_MaNhan ON dbo.MonAnNhan(MaNhan, MaMonAn);
	GO

	USE QuanLyThucDon;
GO

CREATE OR ALTER PROCEDURE dbo.SpCapMaMoi
    @LoaiMa SYSNAME,
    @MaMoi NVARCHAR(20) OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @TienTo NVARCHAR(10);
    DECLARE @SoMoi BIGINT;

    UPDATE dbo.QuyUocMaHeThong WITH (UPDLOCK, HOLDLOCK)
    SET
        @TienTo = TienTo,
        @SoMoi = SoHienTai = SoHienTai + 1
    WHERE LoaiMa = @LoaiMa;

    IF @@ROWCOUNT = 0
    BEGIN
        THROW 52101, N'Loại mã không tồn tại.', 1;
    END;

    SET @MaMoi =
        @TienTo +
        CASE
            WHEN @SoMoi < 1000
                THEN RIGHT(N'000' + CONVERT(NVARCHAR(20), @SoMoi), 3)
            ELSE CONVERT(NVARCHAR(20), @SoMoi)
        END;
END;
GO

