(N'CT209',N'Lòng đỏ trứng gà',N'DVT005',2),(N'CT209',N'Bột bắp',N'DVT001',20),(N'CT209',N'Nước cốt dừa',N'DVT003',70),(N'CT209',N'Vani',N'DVT007',0.5),(N'CT209',N'Bơ lạt',N'DVT001',20),(N'CT209',N'Sữa tươi không đường',N'DVT003',125),(N'CT209',N'Bột mì số 8',N'DVT001',290),(N'CT209',N'Men nở',N'DVT001',3),(N'CT209',N'Đường',N'DVT001',75),(N'CT209',N'Muối',N'DVT001',2),(N'CT209',N'Bột nở',N'DVT001',4),(N'CT209',N'Whipping cream',N'DVT001',65),(N'CT209',N'Lòng trắng trứng',N'DVT005',1),(N'CT209',N'Tangzhong',N'DVT001',90),(N'CT209',N'Củ dền',N'DVT005',0.5);

INSERT dbo.ThanhPhanCongThuc(MaThanhPhan,MaCongThuc,MaNguyenLieu,MaDonVi,SoLuong)
SELECT CONCAT(N'TP',RIGHT(i.CT,3),RIGHT(N'00'+CONVERT(NVARCHAR(2),ROW_NUMBER() OVER(PARTITION BY i.CT ORDER BY i.Ten)),2)),i.CT,n.MaNguyenLieu,i.DonVi,i.SoLuong
FROM @I i JOIN dbo.NguyenLieu n ON n.TenNguyenLieu=i.Ten
WHERE NOT EXISTS(SELECT 1 FROM dbo.ThanhPhanCongThuc t WHERE t.MaCongThuc=i.CT AND t.MaNguyenLieu=n.MaNguyenLieu);

DECLARE @B TABLE(CT NVARCHAR(20),ThuTu INT,NoiDung NVARCHAR(1500));
INSERT @B VALUES
(N'CT201',1,N'Sơ chế tôm và thịt ba chỉ, cắt hạt lựu; ướp với hành tím, tỏi, nước mắm, đường và tiêu 30 phút.'),(N'CT201',2,N'Phi tỏi với dầu màu điều, xào tôm thịt 5–10 phút cho săn.'),(N'CT201',3,N'Nhúng bánh tráng cho mềm, cho nhân vào cuốn; hấp khoảng 8 phút.'),(N'CT201',4,N'Làm mỡ hành và nước chấm tỏi ớt, dùng bánh khi còn nóng.'),
(N'CT202',1,N'Đánh bông whipping cream với đường, tán nhuyễn cơm sầu riêng và giữ lạnh.'),(N'CT202',2,N'Trộn bột nếp, bột bắp, đường, muối, sữa nóng và nước cốt dành dành; lọc qua rây.'),(N'CT202',3,N'Hấp bột 30 phút, trộn bơ, nhồi 5 phút rồi làm lạnh 45 phút.'),(N'CT202',4,N'Cán bột, cho whipping cream và sầu riêng vào giữa, gói thành viên mochi.'),
(N'CT203',1,N'Đánh lòng đỏ trứng với đường và muối.'),(N'CT203',2,N'Đun ấm whipping cream, trộn với trứng và vani rồi lọc.'),(N'CT203',3,N'Rót vào khuôn đặt trong khay nước.'),(N'CT203',4,N'Nướng 150 độ C khoảng 30–45 phút, làm lạnh.'),(N'CT203',5,N'Rắc đường lên mặt và khò đến khi chuyển màu nâu; trang trí dâu tây.'),
(N'CT204',1,N'Ngâm nho khô với rượu rum 15 phút; trộn và rây bột, bột nở, muối.'),(N'CT204',2,N'Đánh bơ với đường, cho lần lượt trứng vào đánh mịn.'),(N'CT204',3,N'Trộn hỗn hợp bột, sữa, vani và nho khô.'),(N'CT204',4,N'Cho vào khuôn, rắc hạnh nhân và nướng 155 độ C trong 40–55 phút.'),
(N'CT205',1,N'Nấu đường thốt nốt với 30ml nước, thêm nước cốt dừa rồi để nguội bớt.'),(N'CT205',2,N'Rây bột năng và bột gạo vào hỗn hợp đường, trộn mịn.'),(N'CT205',3,N'Đánh tan trứng, trộn vào bột và để nghỉ 20–25 phút.'),(N'CT205',4,N'Làm nóng khuôn, thêm bột nở và muối nở rồi nướng 160 độ C khoảng 50 phút.'),
(N'CT206',1,N'Pha men với sữa, trộn bột và phần sữa còn lại; nhào mịn, chia 10 phần và ủ 45 phút.'),(N'CT206',2,N'Luộc trứng cút; ngâm, rửa và băm nấm mèo; trộn nhân thịt với hành tím, dầu hào, hạt nêm, tiêu.'),(N'CT206',3,N'Bọc trứng cút bằng nhân thịt, gói trong vỏ bánh.'),(N'CT206',4,N'Đặt bánh lên giấy nến và hấp khoảng 25 phút.'),
(N'CT207',1,N'Băm thịt, ngâm miến, nấm mèo và nấm hương; cắt trứng luộc, cà rốt và hành tây; trộn nhân.'),(N'CT207',2,N'Kích hoạt men với sữa ấm và đường 10 phút.'),(N'CT207',3,N'Nhồi bột mì, sữa, dầu ăn, tinh bột bắp, bột nở, muối và sữa bột; ủ 30 phút–1 giờ.'),(N'CT207',4,N'Cán bột, cho nhân vào, ủ lần hai 30 phút rồi hấp 13–15 phút.'),
(N'CT208',1,N'Ngâm gelatin; tách lòng đỏ và trộn vani.'),(N'CT208',2,N'Đun sữa với đường, cho lòng đỏ và gelatin vào khuấy; thêm kem tươi, lọc và làm lạnh 1 giờ.'),(N'CT208',3,N'Xay xoài với gelatin, sữa chua và nước cốt chanh dây; lọc qua rây.'),(N'CT208',4,N'Đổ lớp xoài lên lớp sữa và làm lạnh ít nhất 4 giờ.'),
(N'CT209',1,N'Sên lòng đỏ, đường, sữa, nước cốt dừa và bột bắp; thêm vani, muối và bơ, chia nhân.'),(N'CT209',2,N'Làm tangzhong; kích hoạt men; trộn bột mì, đường, muối, bột nở, whipping cream, lòng trắng và tangzhong; ủ 2 giờ.'),(N'CT209',3,N'Cán vỏ, bọc nhân, tạo hình đào tiên và chấm màu bằng củ dền.'),(N'CT209',4,N'Hấp bánh khoảng 20 phút.');

INSERT dbo.BuocCheBien(MaBuoc,MaCongThuc,ThuTu,NoiDung,ThoiGianThucHien)
SELECT CONCAT(N'BCB',RIGHT(b.CT,3),RIGHT(N'00'+CONVERT(NVARCHAR(2),b.ThuTu),2)),b.CT,b.ThuTu,b.NoiDung,NULL
FROM @B b WHERE NOT EXISTS(SELECT 1 FROM dbo.BuocCheBien x WHERE x.MaCongThuc=b.CT AND x.ThuTu=b.ThuTu);

INSERT dbo.DoanPhimHuongDan(MaDoanPhim,MaCongThuc,TieuDe,DuongDan,MoTa)
SELECT N'DP'+RIGHT(m.MaMonAn,3),N'CT'+RIGHT(m.MaMonAn,3),m.Ten,m.Video,N'Video YouTube theo tài liệu nguồn.'
FROM @M m WHERE m.Video IS NOT NULL AND NOT EXISTS(SELECT 1 FROM dbo.DoanPhimHuongDan d WHERE d.MaCongThuc=N'CT'+RIGHT(m.MaMonAn,3));

UPDATE c SET DaCongBo=1 FROM dbo.CongThuc c WHERE c.MaCongThuc BETWEEN N'CT201' AND N'CT209';
GO

SELECT m.MaMonAn,m.TenMonAn,m.ThoiGianChuanBi,m.ThoiGianCheBien,m.DoKho,c.SoKhauPhanChuan,d.DuongDan
FROM dbo.MonAn m JOIN dbo.CongThuc c ON c.MaMonAn=m.MaMonAn
LEFT JOIN dbo.DoanPhimHuongDan d ON d.MaCongThuc=c.MaCongThuc
WHERE m.MaMonAn BETWEEN N'MA201' AND N'MA209';
GO


