(N'Đậu nành khô',N'Đậu nành khô.'),(N'Gelatine bột',N'Gelatine bột.'),(N'Lá dứa',N'Lá dứa.'),(N'Nước để nấu nước đường',N'Nước để nấu nước đường.'),(N'Gừng',N'Gừng.'),
(N'Bột sương sáo đen',N'Bột sương sáo đen.'),(N'Bột sương sáo trắng',N'Bột sương sáo trắng.'),(N'Nước cốt dừa',N'Nước cốt dừa.'),(N'Sữa đặc',N'Sữa đặc.'),(N'Sữa tươi không đường',N'Sữa tươi không đường.'),(N'Hạt é',N'Hạt é.'),(N'Đường',N'Đường.'),(N'Nước',N'Nước.'),
(N'Vải',N'Vải đóng hộp.'),(N'Gelatin',N'Gelatin.'),(N'Kem tươi',N'Kem tươi, whipping cream.'),(N'Hạnh nhân lát',N'Hạnh nhân lát.'),
(N'Đậu đỏ',N'Đậu đỏ.'),(N'Cùi dừa',N'Cùi dừa.'),(N'Nước dền',N'Nước ép củ dền.'),(N'Nước lá dứa',N'Nước lá dứa.'),(N'Bột năng',N'Bột năng.');

;WITH X AS
(
    SELECT Ten,MoTa,ROW_NUMBER() OVER(ORDER BY Ten) + COALESCE((SELECT MAX(TRY_CONVERT(INT, SUBSTRING(MaNguyenLieu, 3, 10))) FROM dbo.NguyenLieu WHERE MaNguyenLieu LIKE N'NL%'), 0) AS N
    FROM @NL AS nl
    WHERE NOT EXISTS (SELECT 1 FROM dbo.NguyenLieu AS n WHERE n.TenNguyenLieu=nl.Ten)
)
INSERT dbo.NguyenLieu(MaNguyenLieu,TenNguyenLieu,MoTa)
SELECT N'NL'+RIGHT(N'000'+CONVERT(NVARCHAR(10),N),3),Ten,MoTa FROM X;
GO

