USE QuanLyThucDon;
GO

BEGIN TRANSACTION;

-- Xóa Bột mì số 8 khỏi công thức CT104
DELETE tp
FROM dbo.ThanhPhanCongThuc tp
JOIN dbo.NguyenLieu nl
    ON nl.MaNguyenLieu = tp.MaNguyenLieu
WHERE tp.MaCongThuc = N'CT104'
  AND nl.TenNguyenLieu = N'Bột mì số 8';

DECLARE @MaGiaVi NVARCHAR(20);

SELECT @MaGiaVi = MaNguyenLieu
FROM dbo.NguyenLieu
WHERE TenNguyenLieu = N'Gia vị thông dụng';

IF @MaGiaVi IS NULL
BEGIN
    SELECT @MaGiaVi =
        N'NL' + RIGHT(
            N'000' + CONVERT(NVARCHAR(10),
            ISNULL(MAX(TRY_CONVERT(INT, SUBSTRING(MaNguyenLieu, 3, 10))), 0) + 1),
            3
        )
    FROM dbo.NguyenLieu
    WHERE MaNguyenLieu LIKE N'NL%';

    INSERT dbo.NguyenLieu
    (
        MaNguyenLieu,
        TenNguyenLieu,
        MoTa
    )
    VALUES
    (
        @MaGiaVi,
        N'Gia vị thông dụng',
        N'Đường, muối, hạt nêm hoặc tiêu tùy khẩu vị.'
    );
END;

IF NOT EXISTS
(
    SELECT 1
    FROM dbo.ThanhPhanCongThuc
    WHERE MaCongThuc = N'CT104'
      AND MaNguyenLieu = @MaGiaVi
)
BEGIN
    INSERT dbo.ThanhPhanCongThuc
    (
        MaThanhPhan,
        MaCongThuc,
        MaNguyenLieu,
        MaDonVi,
        SoLuong
    )
    VALUES
    (
        N'TP10413',
