USE QuanLyThucDon;
GO

BEGIN TRANSACTION;

UPDATE nl
SET 
    nl.TenNguyenLieu = N'Gia vị thông dụng (đường, muối, hạt nêm, tiêu)',
    nl.MoTa = N'Gia vị thông dụng gồm đường, muối, hạt nêm và tiêu.'
FROM dbo.NguyenLieu nl
WHERE nl.TenNguyenLieu = N'Gia vị thông dụng';

UPDATE tp
SET 
    tp.SoLuong = 1,
    tp.MaDonVi = N'DVT014'
FROM dbo.ThanhPhanCongThuc tp
JOIN dbo.NguyenLieu nl 
    ON nl.MaNguyenLieu = tp.MaNguyenLieu
WHERE tp.MaCongThuc = N'CT104'
  AND nl.TenNguyenLieu =
      N'Gia vị thông dụng (đường, muối, hạt nêm, tiêu)';

COMMIT TRANSACTION;
GO

SELECT 
    nl.TenNguyenLieu,
    tp.SoLuong,
    dv.TenDonVi
FROM dbo.ThanhPhanCongThuc tp
JOIN dbo.NguyenLieu nl 
    ON nl.MaNguyenLieu = tp.MaNguyenLieu
JOIN dbo.DonViTinh dv 
    ON dv.MaDonVi = tp.MaDonVi
WHERE tp.MaCongThuc = N'CT104'
  AND nl.TenNguyenLieu LIKE N'Gia vị thông dụng%';
  
  
  USE QuanLyThucDon;
GO

