(MaBuoc, MaCongThuc, ThuTu, NoiDung, ThoiGianThucHien)
VALUES
(N'BCB23005', N'CT230', 5,
N'~ Thành phẩm ~

Vậy là tô phở bò nấu từ gói gia vị phở chỉ với vài bước cơ bản đã hoàn thành rồi.

Nước dùng thì đậm đà, ngọt thanh từ xương, hành tím, hành tây xen lẫn mùi gừng thơm phức kết hợp với thịt bò mềm, béo ngậy cùng bánh phở mềm, dai. Tất cả tạo nên tô phở bò hấp dẫn, thơm ngon khó lòng mà chối từ.',
NULL);

UPDATE dbo.CongThuc
SET DaCongBo = 1
WHERE MaCongThuc = N'CT230';

COMMIT TRANSACTION;
GO
USE QuanLyThucDon;
GO

INSERT INTO dbo.ThanhPhanCongThuc
(
    MaThanhPhan,
    MaCongThuc,
    MaNguyenLieu,
    MaDonVi,
    SoLuong
)
SELECT
    N'TP20699',
    c.MaCongThuc,
    nl.MaNguyenLieu,
    N'DVT014',
    1
FROM dbo.CongThuc c
JOIN dbo.MonAn m
    ON m.MaMonAn = c.MaMonAn
JOIN dbo.NguyenLieu nl
    ON nl.TenNguyenLieu = N'Hạt nêm/tiêu xay'
WHERE m.TenMonAn = N'Bánh bao nhân thịt trứng'
  AND NOT EXISTS
  (
      SELECT 1
      FROM dbo.ThanhPhanCongThuc tp
      WHERE tp.MaCongThuc = c.MaCongThuc
        AND tp.MaNguyenLieu = nl.MaNguyenLieu
  );
GO

