UPDATE dbo.MonAn
SET MoTa = N'Bánh bao nhân thịt trắng nõn nà, bông xốp cùng phần nhân đậm vị, dai dai lạ miệng. Món bánh vừa thơm ngon vừa dễ làm, chắc chắn thực hiện thành công ngay lần đầu.'
WHERE TenMonAn = N'Bánh bao nhân thịt trứng';
