WHERE MaCongThuc = N'CT206';

DELETE FROM dbo.BuocCheBien
WHERE MaCongThuc = N'CT206';

INSERT dbo.BuocCheBien
(MaBuoc, MaCongThuc, ThuTu, NoiDung, ThoiGianThucHien)
VALUES
(N'BCB20601', N'CT206', 1,
N'~ Trộn bột bánh ~

Bạn cho 50ml sữa tươi không đường vào tô, sau đó lấy gói men nhỏ trong bịch bột pha với sữa tươi khuấy cho tan.

Tiếp theo, cho phần bột bánh vào thau tạo 1 lỗ ở giữa (nhớ để lại khoảng 2 muỗng canh bột khô nha), rồi cho phần men pha sữa tươi vào trộn đều, tiếp tục cho 340ml sữa tươi còn lại vào trộn đều để bột và sữa hòa vào nhau.',
10);

INSERT dbo.BuocCheBien
(MaBuoc, MaCongThuc, ThuTu, NoiDung, ThoiGianThucHien)
VALUES
(N'BCB20602', N'CT206', 2,
N'~ Nhào và ủ bột ~

Cho phần bột khô còn lại ra bàn, sau đó cho khối bột trộn sữa lên nhào, đập và cán bột cho thật mịn khoảng 10 - 20 phút đến khi bột không dính tay là được nhé!

Bạn tạo bột thành khối, sau đó chia khoảng 10 phần bột bằng nhau, dùng cán bột cán thật mỏng, rồi cho miếng bột đã cán vào tô, dùng màng bọc thực phẩm bọc kín lại, phủ thêm 1 lớp khăn, ủ bột khoảng 45 phút.

Lưu ý: Nhào bột bánh bao không yêu cầu tạo được màng căng như bánh mì, bạn chỉ cần nhào đến khi bột thành khối mềm dẻo, bề mặt nhẵn láng, sờ vào không dính tay là đạt.',
45);

INSERT dbo.BuocCheBien
(MaBuoc, MaCongThuc, ThuTu, NoiDung, ThoiGianThucHien)
VALUES
(N'BCB20603', N'CT206', 3,
N'~ Làm nhân bánh ~

Trứng cút luộc khoảng 10 phút trên lửa vừa cho chín thì vớt ra bóc bỏ vỏ.

Nấm mèo bạn ngâm trong nước khoảng 10 - 15 phút cho nở rồi mang nấm đi rửa sạch, để ráo, băm nhuyễn.

Cho thịt heo xay vào tô, thêm nấm mèo băm nhỏ, hành tím băm nhỏ, 1.5 muỗng canh hạt nêm, 2 muỗng canh dầu hào, 2 muỗng cà phê tiêu, 1 muỗng canh dầu ăn, trộn đều.',
20);

INSERT dbo.BuocCheBien
(MaBuoc, MaCongThuc, ThuTu, NoiDung, ThoiGianThucHien)
VALUES
(N'BCB20604', N'CT206', 4,
N'~ Gói bánh ~

Bạn thoa 1 ít dầu ăn vào tay, sau đó lấy 1 ít nhân cho trứng cút vào giữa bọc kín lại vo tròn nhân thịt.

Tiếp theo, bạn lấy 1 miếng bột đã ủ cho nhân vào giữ rồi từ từ gấp các mí bột lại tạo hình bánh bao.

Cuối cùng bạn dán 1 lá ngò rí lên đầu bánh bao là hoàn thành nha!

Lưu ý: Để dễ tạo hình bánh bao bạn có thể dùng chén (chén ăn cơm) úp xuống vỏ bánh tạo hình tròn trước khi cho nhân vào nhé!',
15);

INSERT dbo.BuocCheBien
(MaBuoc, MaCongThuc, ThuTu, NoiDung, ThoiGianThucHien)
VALUES
(N'BCB20605', N'CT206', 5,
N'~ Hấp bánh ~

Bạn bắc xửng hấp lên bếp, cho ít rễ ngò rí vào nồi nước. Đặt phần xửng hấp lên trên, lót 1 lớp giấy nến rồi cho bánh bao vào đậy nắp lại, hấp khoảng 25 phút trên lửa vừa thì bánh sẽ chín nhé!

Lưu ý: Cho rễ ngò rí vào nồi nước hấp bánh bao sẽ giúp giúp vỏ bánh bao thơm ngon hơn nhé!',
25);

INSERT dbo.BuocCheBien
(MaBuoc, MaCongThuc, ThuTu, NoiDung, ThoiGianThucHien)
VALUES
(N'BCB20606', N'CT206', 6,
N'~ Thành phẩm ~

Bánh bao nhân thịt trứng bằng bột pha sẵn thơm ngon nóng hổi. Vỏ bánh mềm xốp, nhân bánh vừa ăn không bị khô.

Chiêu đãi gia đình mình bằng món bánh này chắc chắn sẽ làm gia đình bạn tấm tắc khen bạn khéo tay lắm nha!',
NULL);

UPDATE dbo.CongThuc
SET DaCongBo = 1
WHERE MaCongThuc = N'CT206';

COMMIT TRANSACTION;
GO